quests[12904] = { id = 12904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Won't Grant Me Vengeance", description = "They... They killed my brother.\n\n<Gerk fights back tears.>\n\nSlaughtered him like he was some sort of animal. Now they got him laid out on one of their tables on the other side of the camp, ready for their grisly experiments. Dargath's dead too. The paladin made a heroic stand at the ruins to the northeast, but the leader of the Vargul, Algar, was too strong.\n\nI'm all that's left and I'll be dead soon too. I... I'm turning.\n\nIf the Light won't grant me vengeance, maybe you will, {class}. Kill them all.", sourceObjective = "Gerk at Thrym's End in Zul'Drak wants you to kill 15 Vargul.", progress = "You're doing the world a favor, friend. These monsters must be stopped!", completion = "<Gerk is dying.>\n\nTh... They say these Vargul are the... the ones that weren't found worthy by the Lich King. Can... Can you im... imagine it? Just th... think how powerful the... the... worthy must be...\n\nI'll say a prayer for you in the hereafter, hero... May you never have to face them in number.", sourceObjectiveStatus = "unverified-source-field" }
quests[12905] = { id = 12905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mildred the Cruel", description = "Our deal is made then, {name}.  You help me get out of these chains and I'll help you find your little green friend.\n\nThe Hyldnir who runs this mine is known as Mildred the Cruel -- and with good reason.\n\nTell her you've been sent to lend a hand with the mines.  Do whatever she asks until she trusts you with the keys to my shackles.", sourceObjective = "Speak to Mildred the Cruel inside the Forlorn Mine.", completion = "I was expecting a replacement for one of my overseers.  It's about time you showed up.\n\nLet's put you to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12906] = { id = 12906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discipline", description = "Let's start you off with something straightforward.  The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.\n\nOnce in a while, one of them will lose their motivation.  Find any uncooperative vrykul and put them in their place.\n\nTake this disciplining rod.  You'll want to inflict pain, not death.  Well, most of the time anyway.", sourceObjective = "Mildred the Cruel at the Forlorn Mine wants you to use the Disciplining Rod on 6 Exhausted Vrykul.", progress = "Is it done?  I hope you didn't slay too many of the mongrels.  We need the manpower.", completion = "Not bad for a new overseer.  I've another task for you if you're feeling brave today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12907] = { id = 12907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examples to be Made", description = "For every action there is an opposite reaction, sister.  In the case of us applying pressure on the males, this has meant newly spread rumors of insurrection.\n\nThe bearded pig behind this rabble-rousing is called Garhal.  Put an end to him... and make sure the other males see his demise.  They must learn that insubordination will not be tolerated.", sourceObjective = "Mildred the Cruel at the Forlorn Mine wants you to slay Garhal.", progress = "You're back.  Did you kill the insubordinate pig?", completion = "If I had any reservations regarding your commitment when you first arrived, I no longer have any.  With just a little more effort you could be a permanent member of my operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12908] = { id = 12908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Certain Prisoner", description = "You are without mercy.  You will do well around these parts.\n\nI have another task to ask of you.  There is a female vrykul prisoner that's become more of a liability than I had anticipated.\n\nShe had the gall to claim the right to take part in the Hyldsmeet, our sacred competition of strength and fighting prowess.\n\nHere's the key to her shackles.  Make it as painless as possible.  She's a female after all, even if not one of us.", sourceObjective = "Take Mildred's Key to Lok'lira the Crone in the Forlorn Mine.", progress = "It's about time.", completion = "I knew you'd be back!  Get me out of these shackles and I'll help you find the goblin.", sourceObjectiveStatus = "unverified-source-field" }
quests[12909] = { id = 12909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nose Knows", description = "In order to track down Brann, we're going to need a creature with a keen sense of smell and a good tracking ability. There weren't any hounds on the zeppelin, but I think I have a substitute.\n\nAfter the crash, I sent Khaliisi down the east face of the mountain to start hunting for food. Her cat, Frostbite, excels at tracking prey in the snow. Tell her that she'll have to part with her companion for a while, at least. She can hunt on her own, but we have no other way of catching up to Brann Bronzebeard.", sourceObjective = "Speak with Khaliisi at the foot of the mountain east of the Grom'arsh Crash-Site.", completion = "So Boktar has volunteered Frostbite for an errand, eh? Well, this had better be important. He knows better than to try to separate a hunter from her pet!", sourceObjectiveStatus = "unverified-source-field" }
quests[12910] = { id = 12910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "Boktar can have his way this time, but I'll expect him to make it up to me. Don't look at me like that. Boktar may be in command, but no one tells a hunter what to do.\n\n'Put that beast away,' he says. 'Make it stop growling.'\n\nAll of a sudden he changes his mind when it suits him. Next time he complains, Frostbite'll just nip him a bit. Don't worry, she'll do an admirable job tracking your prey. After she locates her target, you're on your own to deal with iron dwarves, or Brann, or whatever you find.", sourceObjective = "Mount Frostbite and ride her to the source of the scent from Brann's note. Then, recover Brann's Communicator and use it to make contact with Brann Bronzebeard.", progress = "Who... who're you?", completion = "<An image of a dwarf appears as you activate the communicator. It can only be Brann Bronzebeard.>\n\n<From the look on his face, Brann seems shocked to see you and begins gesturing furiously.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test", description = "/wave at me and I'll assign 'kill credit to player' to you.", sourceObjective = "/wave at Kill Credit Test", sourceObjectiveStatus = "unverified-source-field" }
quests[12912] = { id = 12912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Storm Approaches", description = "You are not like the others, little one. You do not reek of the ancient death. Perhaps you can be trusted.\n\nI am Gymer, king of the storm giants. I was lured here by my brother, Thiassi, now an undead servant of the Lich King. By the time I realized that his cry for help was a trap, it was too late. I am now a prisoner of the Scourge and I fear that soon I will suffer the same fate as many of the other storm giants.\n\nFind a way to release me from this cage and I will aid you to the best of my ability.", sourceObjective = "Gymer, King of Storm Giants, has asked you to find a way to release him from his cage. Speak with Engineer Reed at the Crusader Forward Camp.", completion = "A... A storm giant? I don't know about this, {name}. That sounds risky. On the other hand, I don't think we have too many other options.\n\nIf I do this you have to promise me that you will get your giant friend to help us deal with Navarius and his cronies.", sourceObjectiveStatus = "unverified-source-field" }
quests[12913] = { id = 12913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak Orcish, Man!", description = "<Brann begins gesticulating wildly and rambling in his native language.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\n Gar Ruk dagUm loch angor-magi ta har ruk!\n\n<After a few moments, you realize the conversation is going nowhere. Perhaps the shaman, Moteha Windborn, at the Grom'arsh Crash-Site will know what to do.>", sourceObjective = "Speak with Moteha Windborn at the Grom'arsh Crash-Site.", completion = "Boktar will not be happy that you didn't find Brann, but at least you didn't come back empty-handed. Now, let's see what we can do about this babbling dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12914] = { id = 12914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gymer's Salvation", description = "Now you say that he's locked up in a 100 foot tall cage, eh?\n\nIf my calculations are correct, we should be able to at least weaken the hinges on the cage, giving the giant enough leeway to break out.\n\nIf this is going to work I'm going to need some plasticizers and stabilizers.\n\nBanshee essence should do nicely for the plasticizer. You can get that from the banshees in the Dead Fields, northeast of us. The stabilizer can be found on the earthragers to the southwest, near Ebon Watch.\n\nGet a move on!", sourceObjective = "Engineer Reed at Crusader Forward Camp in Zul'Drak wants you to bring him 6 Banshee Essence and 6 Diatomaceous Earth.", progress = "Without the plasticizers and stabilizers I'll never be able to make the explosives necessary to break your friend out of jail.", completion = "Thankfully we weren't in short supply of explosives. Putting together the jumbo seaforium charge should be no problem with the materials you brought me.", sourceObjectiveStatus = "unverified-source-field" }
quests[12915] = { id = 12915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Fences", description = "If I hope to wrest control of the Temple of the Makers from my brother, I must make amends with my old allies.\n\nPerhaps by eliminating a common enemy, we may at least take a step towards renewing my friendship with the frost giants.\n\nFjorn has besieged Dun Niffelem with giants of iron. You must defeat him at Fjorn's Anvil, far to the east of here, and weaken his forces sufficiently for the Sons of Hodir to emerge victorious.\n\nTake this charm, {name}. Use it to summon my earthen to your aid.", sourceObjective = "Thorim at the Temple of Storms wants you to Kill Fjorn and 5 Stormforged Iron Giants at Fjorn's Anvil, east of Dun Niffelem.\n\nUsing Thorim's Charm of Earth will summon his Earthen to fight by your side. The charm requires a Granite Boulder from nearby Fjorn's Anvil.", progress = "Does Fjorn still live, {class}?", completion = "So, it is done then.\n\nLet us hope it is enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[12916] = { id = 12916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Only Hope", description = "What I'm about to give you is called seaforium. It is a highly volatile explosive with some unique properties. Due to its malleable nature, you will be able to fill in the hinges and cracks of the cage for maximum damage.\n\nReturn to your friend and use the jumbo seaforium charge to set him free.\n\nLet's hope he honors the bargain. He's our only hope.", sourceObjective = "Speak to Gymer at Thrym's End in Zul'Drak once you have used the Jumbo Seaforium Charge to open the Scourge Enclosure that is holding him prisoner.", progress = "I am a giant of my word, little one.", completion = "FREEDOM!\n\nDo not be afraid, little one. Gymer is an honorable giant. Like you and your people, I too wish to see the Scourge driven away from this land and the Lich King destroyed. I will help you, as promised, to the best of my ability.", sourceObjectiveStatus = "unverified-source-field" }
quests[12917] = { id = 12917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with the Wind's Voice", description = "I suppose we shouldn't have expected to find Brann so easily, not with our luck. If we can make sense of what Brann is saying, you can persuade him to give up his location.\n\nThe power of the wind is strong in these mountains, and it may prove a great boon to us. A knowledgeable shaman can hear the sound of all the world's tongues on the wind.\n\nTo the northwest, on the Snowdrift Plains, you will find beings made of wind, the stormriders. Capture their voices and bring them to me.", sourceObjective = "Bring 5 Voices of the Wind to Moteha Windborn at the Grom'arsh Crash-Site.", progress = "Have you brought the wind's voices?", completion = "You should be able to communicate with the dwarf now. Ask Boktar what he requires of you. There is little time to lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[12918] = { id = 12918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "It has the cold of the Icewyrm's breath up here does it not?   Not only do I lack customers for my crafting skills, but I also lack stock of gems to sell!   If you can bring me several uncut gems to replenish my stocks, I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Ounhulo in Valgarde.", progress = "You are most generous.   The least I can do is to teach you the skills of gem perfection.", completion = "These are perfect for replenishing my stock.   Not only will I teach you the art of gemcutting perfection, but I cut one of them gems into its perfect form which you may have as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[12919] = { id = 12919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm King's Vengeance", description = "My people have been decimated by the Lich King. The Scourge now use the corpses of storm giants to create mindless flesh giants, or worse, stitched together aberrations like Thrym.\n\nI will stop at nothing to see them all driven from this world. We will work together to destroy the Scourge that threaten Zul'Drak.\n\nWe will kill them all: Navarius, Algar and Thrym!\n\nWhen you are ready, let me know and we will begin our destructive journey.", sourceObjective = "Speak with Gymer to begin.\n\nWhile riding Gymer, destroy 100 Scourge and kill Algar the Chosen, Thrym and Prince Navarius. Report to Crusader MacKellar at Crusader Forward Camp should you succeed.", progress = "What is going on? Are our enemies dead?", completion = "Unbelievable! This will be a story for the ages, {name}! One man rode upon the head of the king of storm giants and decimated an entire Scourge army!\n\nAnd I was there to see it all happen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12920] = { id = 12920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching up with Brann", description = "What are you waiting for? The language barrier has been broken, thanks to Moteha. Contact Brann Bronzebeard and find out anything you can about where he's hiding and what he's chasing after.\n\nMaybe we can still salvage something from this disaster.", sourceObjective = "Use Brann's Communicator to contact Brann Bronzebeard and speak with him, then speak to Boktar Bloodfury at the Grom'arsh Crash-Site.\n\nIf you lose Brann's Communicator, speak with Moteha Windborn at the Grom'arsh Crash-Site.", progress = "What did you find out?", completion = "<Boktar listens as you describe your conversation with Brann.>\n\nThere's truth to the dwarf's words. Vor'takh's plan is not the way of the Horde. If Brann Bronzebeard knows of a way to stop these iron dwarves and their patron, it serves us to help him.", sourceObjectiveStatus = "unverified-source-field" }
quests[12921] = { id = 12921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Scenery", description = "Excellent.  There's an exit in the eastern end of the mine that leads to Brunnhildar Village.  Follow it and I'll meet you there.\n\nWe must not be seen together so no one suspects you of aiding me.  I'll use my magic to disguise my appearance.  Do not worry, {race} -- we'll find your friend in no time.", sourceObjective = "Reconvene with Lok'lira the Crone in Brunnhildar Village.", completion = "You're here -- good.  I think I know where your goblin is.", sourceObjectiveStatus = "unverified-source-field" }
quests[12922] = { id = 12922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Refiner's Fire", description = "Beneath its porous exterior, this hunk of metal gleams with a mysterious quality.\n\nYou feel it would only be prudent to burn off the slag at Fjorn's Anvil.\n\nAs you ponder where in this frozen waste you might find something hot enough for the job, a fire revenant crosses your path...", sourceObjective = "You must collect 10 Furious Sparks from the Seething Revenants at Frostfield Lake and then use the anvil at Fjorn's Anvil.", progress = "The surface of the anvil is scalding, in sharp contrast with the wintry air.", completion = "You place the metal on the anvil and immediately upon adding the sparks they work the ore furiously.\n\nWhen at last they burn out, you are left with a large piece of metal that gleams with a light of its own.", sourceObjectiveStatus = "unverified-source-field" }
quests[12924] = { id = 12924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging an Alliance", description = "<Thorim, for the first time since your meeting him, smiles.>\n\nThis is all beginning to have the smell of fate's hand, {race}.\n\nYour discovery is what remains of my armor, long ago cast off in a fit of grief and left to the elements. Only the sons of Hodir are capable of its reforging, for they are its original creators.\n\nPerhaps you've done enough to soften their hatred of me. Seek out their king, Jokkum, if he still breathes.\n\nFind your way into his good graces and plead for his assistance.", sourceObjective = "You are to go to Dun Niffelem and ask King Jokkum to allow Thorim's armor to be reforged. After completing Jokkum's task, you are to speak with Njormeld in Dun Niffelem.", completion = "It would seem that I have refined my technique considerably. That, or the legends surrounding this anvil are true.\n\nThis suit of armor is superior to the last, and took less material to create.\n\nWith the excess, I was able to fashion you a little something as payment for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12925] = { id = 12925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations", description = "The Lich King sent emissaries to us on three different occasions.  All three were promptly dismembered.\n\nOur sisters in Valkyrion were not as dedicated to our traditions and accepted the Scourge's advances.  Now instead of capturing their drakes from the wild, they raise them from the blight and filth that the Scourge wallow in.\n\nTake the frost oil that the Valkyrion Hyldnir carry on them and use it to freeze any blighted eggs you find.  Rumors speak of a fetid pool of blight where the eggs are kept.", sourceObjective = "Thyra Kvinnshal in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", progress = "Did you destroy the blighted eggs?", completion = "You have our thanks, sister.  We cannot allow our valiant traditions to be corrupted.", sourceObjectiveStatus = "unverified-source-field" }
quests[12926] = { id = 12926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of the Puzzle", description = "We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.", sourceObjective = "Use Brann's Communicator to contact Brann Bronzebeard and find out what to do next.", progress = "Did you complete the disk?", completion = "That was quick! Now that we have the disk, we have to find out how to use it to unlock the first half of the archive key.", sourceObjectiveStatus = "unverified-source-field" }
quests[12927] = { id = 12927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", sourceObjective = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not, lad. You'll have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Keeper Mimir to be systematic.", sourceObjectiveStatus = "unverified-source-field" }
quests[12928] = { id = 12928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", sourceObjective = "Recover Norgannon's Shell from Archivist Mechaton.", progress = "Did you find Norgannon's shell?", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. I've had Archaeologist Andorin on the lookout for clues to the shell's whereabouts for a long time. He's never going to believe me when I tell him it was an intrepid {race} who found it instead.", sourceObjectiveStatus = "unverified-source-field" }
quests[12929] = { id = 12929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen of Ulduar", description = "The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.\n\nThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, {name}.", sourceObjective = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the fight for Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12930] = { id = 12930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Earth", description = "It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.\n\nAs the irons beat us back, even the strongest find themselves failing.\n\nWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?", sourceObjective = "Use the Earthen Mining Pick to mine 7 clumps of Enchanted Earth. Bring the earth and 5 Frostweave Cloth to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Were you able to find any of the earth?", completion = "This will allow us to patch up more of the fallen. Thank you, {name}, on behalf of all who defend the refuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12931] = { id = 12931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Back", description = "The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.\n\nWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.\n\nKill any of the stormforged or their creations you encounter outside the refuge.", sourceObjective = "Bouldercrag the Rockshaper wants you to slay 10 Stormforged Attackers and return to him at Bouldercrag's Refuge. You may kill either Stormforged Raiders or Stormforged Reavers.", progress = "How goes the battle?", completion = "You've given the defenders something to cheer about. Seeing the enemy fall by your hand has reinvigorated them and bolstered their courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12932] = { id = 12932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.\n\nYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[12933] = { id = 12933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Magnataur!", description = "This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!\n\nWe'll get this party started when you give me the word.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Stinkbeard! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Wow! When I first saw Stinkbeard, I thought you were done for! Nice work!", sourceObjectiveStatus = "unverified-source-field" }
quests[12934] = { id = 12934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: From Beyond!", description = "I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!\n\nIf you think you're up to it, get in there and give 'em hell!", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat one of the elemental lords! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Unbelievable! I thought this whole place was going to explode when it first appeared! You really dominated that round!", sourceObjectiveStatus = "unverified-source-field" }
quests[12935] = { id = 12935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Tuskarrmageddon!", description = "This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!\n\nWe'll start when you're ready.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Orinoko Tuskbreaker! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "I was worried for a while there, {name}. When he busted out the seals and penguins... Well, I didn't know what to think to be honest. It looked pretty damn ridiculous.", sourceObjectiveStatus = "unverified-source-field" }
quests[12936] = { id = 12936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Korrak the Bloodrager!", description = "You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.\n\nAre you ready?", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Korrak the Bloodrager! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Damn, I remember Korrak from way back in my younger days when I used to work for the Frostwolf Clan. He would never shut up! I think you just did the world a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12937] = { id = 12937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relief for the Fallen", description = "The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.\n\nWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.\n\nTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, {name}. Every casualty is one too many.", sourceObjective = "Use the Telluric Poultice to heal 8 Fallen Earthen Defenders, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Have you healed the fallen defenders?", completion = "The warriors that you've healed will aid us in holding the line even longer. If we are to truly be free of the iron threat, we must find a way to strike at them behind the lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[12938] = { id = 12938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Duke", description = "We need you focused, {name}. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.\n\n<The baron chuckles.>\n\nI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.\n\nWere I you, I would not keep him waiting.", sourceObjective = "Speak with Duke Lankral at The Shadow Vault.", completion = "It's a pleasure to finally meet you, {name}. We owe you a great deal, but we're not done with you yet.\n\nThere is a vrykul city just over the mountains to the west, a place called Jotunheim.\n\nThe vrykul there are in a constant state of challenge to 'ascend'. The winners go to Ymirheim to serve as the Lich King's elite warrior caste, the Ymirjar, and the losers are reduced to scourged Vargul.\n\nYou are going to be my instrument to see to it that more Vargul than Ymirjar emerge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12939] = { id = 12939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Challenge", description = "The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.\n\nOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.\n\nI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a {race}, shall we?\n\n<The duke grins, his rotting teeth flashing in the dim light of the vault.>", sourceObjective = "Duke Lankral at The Shadow Vault has asked you to use the Challenge Flag to challenge and defeat 6 Mjordin Combatants.", progress = "Perhaps you could go back and challenge a few more?", completion = "Already I'm hearing reports of the prowess you displayed on the Savage Ledge. Excellent, {name}... excellent!\n\n\n\nAnd now I think it's time to issue a decree to the thane of those vrykul that you so easily defeated.", sourceObjectiveStatus = "unverified-source-field" }
quests[12940] = { id = 12940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12941] = { id = 12941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12942] = { id = 12942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off With Their Black Wings", description = "Traitors.  We Hyldnir have little love for them.\n\nThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!\n\nThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.\n\nYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.", sourceObjective = "Iva the Vengeful in Brunnhildar Village wants you to go to Valkyrion and slay 12 Nascent Val'kyr.", completion = "The val'kyr are nothing but the Lich King's lapdogs.  They will be put down like the scum they are.  They've made their choice, now they have to live with the consequences.", sourceObjectiveStatus = "unverified-source-field" }
quests[12943] = { id = 12943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Vault Decree", description = "Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.\n\nI need him dead!\n\nI've written a decree. Stand before the thane and read it aloud.\n\n<The duke arches his eyebrow in amusement.>\n\nIt should... unnerve him at the least.", sourceObjective = "Duke Lankral at The Shadow Vault has ordered you to read the Shadow Vault Decree in the presence of Thane Ufrang the Mighty, and then to slay him.", completion = "<Duke Lankral nods his approval at your report of success.>\n\nWe face a foe that dwarfs us, not only in stature, but also numerically. If we are to win the battle for Icecrown, we must outthink them!\n\nWith Ufrang dead, that gives us an advantage in Jotunheim. Let us see if we can capitalize on it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12944] = { id = 12944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12945] = { id = 12945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12946] = { id = 12946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12947] = { id = 12947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12948] = { id = 12948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of Anguish", description = "This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!\n\nLet me know when you're ready and we'll start.", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Vladof the Butcher! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "You did it, {name}! That was the most exciting fight yet! What are you going to do with your winnings? Me? I'm going to Dalaran and blowing it all in the Underbelly. Lot of hot action going on down there!", sourceObjectiveStatus = "unverified-source-field" }
quests[12949] = { id = 12949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Key", description = "{class}, the key to my shackles is hanging around the neck of Instructor Hroegar outside.\n\nPerhaps you could retrieve it by separating his head from his shoulders?", sourceObjective = "Vaelen the Flayed at Ufrang's Hall has asked you to retrieve the Key to Vaelen's Chains.", progress = "Do you have it?", completion = "Thank you, {race}. Just hand me the key, I'll take care of it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[12950] = { id = 12950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12951] = { id = 12951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Baron Know", description = "The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.\n\nYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.\n\nI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?\n\nGo on before you get captured, too! I'll see you back at the vault.", sourceObjective = "Speak with Baron Sliver at The Shadow Vault.", completion = "What?! We can ill-afford to lose one death knight, let alone an entire contingent!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[12952] = { id = 12952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing.", progress = "These will do.   I shall teach you the skills of gem perfection.", completion = "These will have to do.  I can teach you the art of gemcutting perfection, and give you proof of my skills as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12953] = { id = 12953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valkyrion Must Burn", description = "The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.\n\nPerhaps Iva will appreciate the extra effort and reward you appropriately.", sourceObjective = "Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.", completion = "Now that is what I call dedication!  Those traitors might have a new master now, but they'll never forget their sisters' parting gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[12954] = { id = 12954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!\n\nYou know the drill, {name}. When you're ready let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Hey! I know you. Your victory at the Ring of Blood was talked about for months! Too bad you forfeited the championship when you failed to show up to defend your title! Easy come, easy go, eh? At least you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[12955] = { id = 12955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Competition", description = "Mrrfrmrfrrmrrr...\n\n<The Leaper clears his throat.>\n\nSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.\n\nI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.\n\nSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.", sourceObjective = "The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.", progress = "Why are you here?\n\nGo and humiliate them!", completion = "That was important, {name}. By driving them off, you're keeping them from interfering with whatever we need you to do over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[12956] = { id = 12956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spark of Hope", description = "Clearly, this is more than an ordinary hunk of metal.\n\nUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.\n\nLooking closer, you can make out one of Thorim's runes shining beneath the surface....", sourceObjective = "You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.", progress = "What have you there, little one?", completion = "You notice Thorim's stern countenance brighten with recognition as you present the ore.", sourceObjectiveStatus = "unverified-source-field" }
quests[12957] = { id = 12957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Stormforged", description = "To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.\n\nI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.\n\nGo to the Frozen Mine, {name}, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.", sourceObjective = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters.", progress = "Have you freed the slaves of the stormforged?", completion = "I had hoped that more of the captives would choose to join us, but I do not blame them. Willing allies are few and far between, and we are thankful that you have lent your blade to our cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[12958] = { id = 12958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Blood Jade Amulet", description = "A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.\n\nYou can find a Vrykul Amulet on any Northrend Vrykul.", progress = "Do you have a Blood Jade Amulet for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12959] = { id = 12959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Glowing Ivory Figurine", description = "A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.", progress = "Do you have a Glowing Ivory Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12960] = { id = 12960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Wicked Sun Brooch", description = "A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.\n\nYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.", progress = "Do you have a Wicked Sun Brooch for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12961] = { id = 12961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Intricate Bone Figurine", description = "A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Proto Dragon Bone on any Northrend Proto Dragon.", progress = "Do you have an Intricate Bone Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12962] = { id = 12962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Bright Armor Relic", description = "A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.\n\nYou can find an Elemental Armor Scrap on any Northrend Revenant.", progress = "Do you have a Bright Armor Relic for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12963] = { id = 12963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Shifting Sun Curio", description = "A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", sourceObjective = "Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.\n\nYou can find a Scourge Curio on any Northrend Scourge.", progress = "Do you have a Shifting Sun Curio for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12964] = { id = 12964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ore", description = "At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.\n\nIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.", sourceObjective = "Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "What have you discovered about the ore?", completion = "<Bouldercrag reaches out to take the ore, but then recoils.>\n\nThat ore... I can't touch it. It seethes with unnatural energy. No creature of stone can handle it. What do they mean to do with this?", sourceObjectiveStatus = "unverified-source-field" }
quests[12965] = { id = 12965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gifts of Loken", description = "The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.\n\nIt could explain the strength and ferocity my men see in the stormforged warriors.\n\nValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, {name}, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.", sourceObjective = "Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Is it true? Does Valduran possess powerful relics of the titans? Did you destroy them?", completion = "<Bouldercrag nods grimly.>\n\nYou've weakened the stormforged considerably, but they'll keep fighting. Their casualties matter nothing to them, while our defenders continue to fall. Even if it costs them a hundred or a thousand iron corpses, they'll keep fighting until we've been pounded to gravel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12966] = { id = 12966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Miss Him", description = "<Jokkum listens patiently to your request, then ponders it carefully before responding.>\n\nSo it is you we have to thank for Fjorn's demise?\n\nWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.\n\nFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.\n\nNjormeld was sent to recover Fjorn's anvil. You should find him there.", sourceObjective = "King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil.", completion = "Reforging Thorim's armor? It can be done.\n\nFirst though, there's the matter of the anvil...", sourceObjectiveStatus = "unverified-source-field" }
quests[12967] = { id = 12967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battling the Elements", description = "Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.\n\nWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.\n\nSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, {race}. Guide him against this enemy.", sourceObjective = "Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants.", progress = "Were you able to lead Snorri to another victory, {class}?", completion = "An honorable performance, {race}. I shall inform the king of your assistance.\n\nThe anvil is nearly cool enough. I shall see you in Dun Niffelem soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12968] = { id = 12968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yulda's Folly", description = "The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.\n\nShe ought to have left with a sword through her, but her magic was strong and she managed to escape.\n\nSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.", sourceObjective = "Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion.", progress = "Did you find Yulda?", completion = "Yulda had it coming.  No one gets away with insulting the Hyldsmeet.  Not even one of our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[12969] = { id = 12969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is That Your Goblin?", description = "I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.\n\nYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.", sourceObjective = "Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark. Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded.", progress = "You're back.", completion = "Well done, young one.  It looks like our deal has been satisfied on both our ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[12970] = { id = 12970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hyldsmeet", description = "Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.\n\nThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.\n\nIf you're willing to listen, I've a proposal for you.", sourceObjective = "Listen to Lok'lira the Crone's proposal.", progress = "Keep it down, the others might start getting suspicious.", completion = "It's settled then.  You will compete in the Hyldsmeet and with my help you'll restore great Thorim to his rightful place.", sourceObjectiveStatus = "unverified-source-field" }
quests[12971] = { id = 12971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking on All Challengers", description = "Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.\n\nThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.", sourceObjective = "Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", progress = "Yes, {name}?", completion = "You've done it, {name}.  You've bested some of the fiercest fighters the Hyldnir race has to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12972] = { id = 12972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Bear", description = "You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.\n\nUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.\n\nThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.", sourceObjective = "Speak to Brijana outside Brunnhildar Village.", completion = "Think we'll give you your own bear just like that?  You'll have to prove yourself before you get anything from us.\n\nDo not think too highly of yourself just because you bested a few challengers in the Hyldsmeet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12973] = { id = 12973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", sourceObjective = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", progress = "My pardons, lad! I got all caught up in tha moment and I neglected ye entirely.", completion = "King Stormheart sends his most sincere thanks for reuniting him with his brothers. It seems he's off to settle a score now - perhaps you'll meet with him again on Arthas's doorstep.", sourceObjectiveStatus = "unverified-source-field" }
quests[12974] = { id = 12974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Call!", description = "Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.\n\nYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.\n\nEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!", sourceObjective = "Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak.", completion = "Shifty sent you, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12975] = { id = 12975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Memoriam", description = "Surely Thorim has told you of the tragedy that divides us.\n\nIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.\n\nIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.\n\nGo there, {race}. Collect the fragments of Hodir's Horn that was shattered that day.", sourceObjective = "King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.", progress = "Have you found the pieces of Hodir's Horn?", completion = "Another good deed you have done on Thorim's behalf, {class}.\n\nThis will help to soften the hearts of my people towards him.", sourceObjectiveStatus = "unverified-source-field" }
quests[12976] = { id = 12976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monument to the Fallen", description = "Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.\n\nMay it soothe the pains and heal the scars my people have borne these many years.\n\nMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.\n\nGo now, {class}. Njormeld awaits you.", sourceObjective = "King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem.", progress = "You have brought the fragments of Hodir's Horn, {race}?", completion = "<Njormeld's eyes become noticeably moist as he pours the contents of the bag onto the anvil.>\n\nThe Horn of Hodir....\n\nThis was a sacred gift to our people from Hodir himself, {race}. It is a relic of great importance to us.\n\nWhen you next return to our stronghold you shall see the fruits of your labor.\n\nFarewell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12977] = { id = 12977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Call", description = "You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.\n\nAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.\n\nThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.\n\nAs you set off, you find that your hands have been filled with an ethereal horn.", sourceObjective = "Blow Hodir's Horn over 5 Niffelem Forefathers and 5 Restless Frostborn corpses at Thunderfall.", progress = "Strong gusts of wind swirl around the horn, causing its sound to echo throughout the surrounding mountains.\n\nTo any unknowing passersby, it might seem to be blowing itself....", completion = "You are filled with a sense of peace and contentment knowing that the once tormented souls of Thunderfall are now resting peacefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[12978] = { id = 12978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing the Storm", description = "Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.\n\nWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.\n\nYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.", sourceObjective = "Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems.", completion = "There may be hope for victory, {name}. We have never been able to sustain an attack on the stormforged, but with your efforts, Valduran may yet fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[12979] = { id = 12979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor of Darkness", description = "This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.\n\nWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?\n\nPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.", sourceObjective = "Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What is it you have there?", completion = "Careful, now. Keep that plate as far away from me as you can. Even being in its presence is enough to inflict pain.\n\nBut you're right, {name}, these are gigantic armor plates for a war golem of normal size. What would the stormforged be doing with them? There's only one way to find out.", sourceObjectiveStatus = "unverified-source-field" }
quests[12980] = { id = 12980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Armor's Secrets", description = "The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.\n\nHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.\n\nTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.", sourceObjective = "Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What did you learn?", completion = "<Bruor listens as you describe what you learned in the workshop.>\n\nSo Valduran's master has given him this sinister metal to construct a giant weapon? That must be what he intends to use for the final strike against us! We need to stop him before he's able to complete it and unleash this weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12981] = { id = 12981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot and Cold", description = "As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.\n\nIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.\n\nIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.", sourceObjective = "You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem.", progress = "A luminous blue glow surrounds the anvil.", completion = "You feel a sense of accomplishment as you realize that your efforts continue to strengthen the renewed bonds between Thorim and the Sons of Hodir.", sourceObjectiveStatus = "unverified-source-field" }
quests[12982] = { id = 12982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebon Blade Prisoners", description = "Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.\n\nCan you assist me once more, {name}?\n\nGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.\n\nJust get my men free!", sourceObjective = "Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.", completion = "Thank you, {class}. With the death knights that you freed, we'll be able to hold the line... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12983] = { id = 12983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last of Her Kind", description = "For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.\n\nThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.\n\nIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.\n\nTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern.", progress = "Did you find a matriarch?", completion = "I'm impressed.  I never thought I would see an icemaw matriarch again.  Especially not one this size.", sourceObjectiveStatus = "unverified-source-field" }
quests[12984] = { id = 12984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valduran the Stormborn", description = "We have no choice, {name}. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.\n\nEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.\n\nYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.", sourceObjective = "Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Valduran must be dealt with before the refuge falls.", completion = "At last, Valduran is dead, and the stormforged are weakened, but if his boasting is true, we must continue fighting the stormforged in his absence. This weapon they're building could be the end of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12985] = { id = 12985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a Head", description = "Greetings, {race}.\n\nI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.\n\nI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.\n\nTake this tool, and gather the eyes from the iron giant corpses that litter our fields.", sourceObjective = "Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.", progress = "Have you collected the final components I seek, {race}?", completion = "It is nearly done.\n\nWith this artifact in place, Dun Niffelem shall be warned of impending dangers before they are upon us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12986] = { id = 12986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Titans", description = "Norgannon's Core is not at this location. I am not sure why you seek it, {race}, and I am equally unsure if you truly know the purpose of that which you seek.\n\nI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.", sourceObjective = "Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.", progress = "Have you returned with the knowledge that I seek, {race}?", completion = "The news you bear forth is grave indeed. I do not know the fate of the remaining watchers, but their absence spells dark times for all of the lands of Azeroth.\n\nI shall examine the knowledge contained in the databank that you have returned and attempt to fully assess the situation. I believe I am in possession of knowledge that you deem more pertinent at this moment however, so I shall allow you to partake in said wisdom first.", sourceObjectiveStatus = "unverified-source-field" }
quests[12987] = { id = 12987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing Hodir's Helm", description = "The helm is forged.\n\nYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.\n\nIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.\n\nFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.\n\nEnjoy the privilege, {class}. Never before has an outsider been given such an honor!", sourceObjective = "Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.", progress = "Have you placed Hodir's Helm, {race}?", completion = "<Njormeld gazes up at Hodir's Helm, visibly moved.>\n\nThat will do, little {race}.\n\nThat will do....", sourceObjectiveStatus = "unverified-source-field" }
quests[12988] = { id = 12988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Forges!", description = "In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.\n\nNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, {name}, for it will mean the end of the refuge.\n\nGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.", sourceObjective = "Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Were you able to hamper them by sabotaging the forges?", completion = "Excellent work! Oh, it won't stop the iron dwarves, but it'll take them valuable time to rebuild those forges. I daresay we've gained the advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12989] = { id = 12989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slithering Darkness", description = "The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.\n\nAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.", sourceObjective = "Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.", completion = "The jormungar are vile creatures.  You did well in destroying them.", sourceObjectiveStatus = "unverified-source-field" }
quests[12990] = { id = 12990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormhole", description = "Bring me materials and I'll teach you how to use your Wormhole Generator.You will learn:", sourceObjective = "Bring Jon LeCraft the materials he seeks to avoid a swift death, and to get a cool new spell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12991] = { id = 12991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Them Where it Hurts", description = "Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.\n\nNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.", sourceObjective = "Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge.", completion = "There were days when I could never ask someone to do what you did, but my experience with the iron dwarves has extinguished those feelings. We have bought time against the enemy's advance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12992] = { id = 12992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Dem Vrykuls!", description = "Dem vrykuls at the Jotunheim needs to be crushed!\n\n{name} crush dems good!", sourceObjective = "Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.", completion = "{name} is my bestest little {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12993] = { id = 12993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colossal Threat", description = "You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.\n\nEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.", sourceObjective = "Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Did you find the documents we're looking for?", completion = "<Bouldercrag begins to look over the documents, his eyes wide.>\n\nI had no idea the irons were capable of this! Our men will have no chance against this behemoth if it's completed. Fortunately, it looks like they're still lacking a key part.", sourceObjectiveStatus = "unverified-source-field" }
quests[12994] = { id = 12994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Hunter", description = "The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.\n\nFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips--at least you think you do.\n\nIt would seem that she senses danger outside the stronghold and wants you to do something about it.\n\nWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...", sourceObjective = "You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.\n\nUsing the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.", progress = "The frostworg denmother looks at you curiously.", completion = "As you slide the chain back around the denmother's neck she licks your face approvingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[12995] = { id = 12995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Our Mark", description = "We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.\n\nI want you to demoralize them.\n\nMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.\n\nLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.", sourceObjective = "Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.", progress = "Oh now, {name}, I don't think you're quite done yet.", completion = "Well done, {name}. Let them see the desecrated corpses of their fallen comrades and think twice about striking at us!\n\nIf you come back tomorrow, I will make certain to have more banners prepared for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12996] = { id = 12996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warm-Up", description = "You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.\n\nA good bear won't do you much good without the skill to ride it.\n\nI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.", sourceObjective = "Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak.", progress = "How did it go with the yeti?", completion = "Not bad.  I was hoping Kirgaraak would snap your neck so I could keep your bear.\n\nJust joking, sister.  Well... half-joking.  That's a really nice bear you've got.", sourceObjectiveStatus = "unverified-source-field" }
quests[12997] = { id = 12997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Pit", description = "Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.\n\nHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.\n\nGlory awaits, should you succeed.", sourceObjective = "Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", progress = "Hail, sister.", completion = "You really did it!  You made it out with your health.  Wish we could say the same for your bear.\n\nIt's going to take a while for her to recover.  Fortunately you won't need her for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[12998] = { id = 12998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Storm", description = "According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.\n\nWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!\n\nNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.", sourceObjective = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm.", completion = "With the heart in the hands of Narvir, the colossus will achieve its full power! We'll have no choice but to fight it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12999] = { id = 12999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bone Witch", description = "You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.\n\nThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.\n\nShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.", sourceObjective = "Speak with The Bone Witch within the cave at Njorndar Village.", completion = "{name}, you came.\n\nAlready I have heard of your activities on the Savage Ledge. This is good. I am glad that you seem willing to help with undermining the vrykul here at Jotunheim.\n\n\n\nYou and I are going to have a great deal of fun with them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13000] = { id = 13000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Measures", description = "The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.\n\nWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.\n\nWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.", sourceObjective = "Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.", progress = "Did you bring the furs?", completion = "These furs are rather... large.  I'd hate to see the worgs you had to face off with.\n\nWe're all very thankful.  The temperature is starting to drop already.", sourceObjectiveStatus = "unverified-source-field" }
quests[13001] = { id = 13001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Hodir's Spear", description = "The time has come, little {class}. The stars have foretold of this day.\n\nI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.\n\nWe must obey! Were we to fail in receiving this gift, doom would surely follow.\n\nI call upon you to assist me in this sacred undertaking.\n\nGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.", sourceObjective = "Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters.", progress = "Have you gathered the materials for the spear, {race}?", completion = "Stand back, {race}, and behold the fulfilling of a prophecy!", sourceObjectiveStatus = "unverified-source-field" }
quests[13002] = { id = 13002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "Welcome to de cold, mon.  Dis place may not be so good for keepin' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin' is some gems to do me work on.\n\nBring me some gems and I be teachin' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin' an uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba'li in Warsong Hold.", progress = "Dis is what I been lookin' for.   Now I be learnin' you Gem Perfection.", completion = "Dey be perfect mon'.    Here is the art of gemcutting perfection for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[13003] = { id = 13003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Slay Your Dragon", description = "Hodir's Spear is an icon of great prowess in battle.\n\nIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.\n\nScanning the horizon, your vision locks on a wild wyrm as it flies nearby.\n\nIt is decided. Of you and he, only one shall see the next sunrise....", sourceObjective = "You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.", completion = "It is done.\n\nYou have stared certain death in the face and emerged victorious.\n\nBy single-handedly defeating such a mighty beast, you have brought great honor to Dun Niffelem!", sourceObjectiveStatus = "unverified-source-field" }
quests[13004] = { id = 13004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "There's a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.", sourceObjective = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep.", progress = "Your donation is much appreciated.   Let me teach you of gem perfection.", completion = "Thank you.   I shall teach you of gemcutting perfection and in addition give you a perfect gem that I have cut.", sourceObjectiveStatus = "unverified-source-field" }
quests[13005] = { id = 13005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen Oath", description = "For years I neglected my duties, giving into defeat and self-pity.\n\nNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.\n\nEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.\n\nThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.", sourceObjective = "Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.", progress = "Hail, {name}!  What news do you bring?", completion = "It's a good start.  But my brother's forces will not take long to regroup.  We must make our victory a decisive one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13006] = { id = 13006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Viscous Cleaning", description = "As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.\n\nNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.\n\nJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.", sourceObjective = "You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.\n\nYou are then to return to Dun Niffelem and apply the oil to Hodir's Helm.", progress = "Frost is thickening on the helm as you watch, and icicles are beginning to form around its edges...", completion = "As you coat the helm with a thin layer of oil, the frost falls away and the surface gleams.", sourceObjectiveStatus = "unverified-source-field" }
quests[13007] = { id = 13007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Colossus", description = "We have failed to prevent the completion of the iron colossus, {name}, which means we have no choice but to face it in battle.\n\nBruor has devised a plan to exploit the colossus' only weakness.\n\nNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the iron colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.", sourceObjective = "Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Have you defeated the iron colossus and spared the refuge from destruction?", completion = "We've done it, we've really done it! The refuge is spared and the stormforged are defeated! We must warn Brann before Loken gets it in his mind to try to rebuild his forces. The only way to secure the victory you have won today is to go into Ulduar and defeat Loken for all time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13008] = { id = 13008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge Tactics", description = "We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.\n\nFree our crusaders trapped on the field outside the base, {class}!", sourceObjective = "Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 5 Webbed Crusaders.", completion = "There are still many Argent Crusade soldiers out on that field and in Scourgeholme, {name}. While your help is appreciated, there is still much left to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13009] = { id = 13009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.\n\nMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.", sourceObjective = "Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms.", progress = "How have your efforts fared, {class}?", completion = "<As you present Thorim with the reforged suit of armor, he is visibly stricken by its splendor.>\n\nYou have done well, {race}, but there remains much to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13010] = { id = 13010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krolmir, Hammer of Storms", description = "One task remains before I can reclaim my home at the Terrace of the Makers.\n\nKrolmir must be found.\n\nOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.\n\nI've thought it lost for these many years, but now I must be certain.\n\nReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.", sourceObjective = "Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.", progress = "Back again, little {race}?", completion = "Words cannot express my gratitude, {class}.\n\nYou have served me honorably. Please accept this token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13011] = { id = 13011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling Jorcuttar", description = "I have an opportunity that will help you to gain approval with my people, provided you prevail.\n\nThe jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.\n\nThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.\n\nShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.", sourceObjective = "King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.", progress = "Have you slain Jorcuttar?", completion = "So it is done.\n\nWe have heard the screams of Jorcuttar as they echoed from across the valley.\n\nYou have done our people a service this day, little {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13012] = { id = 13012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sardis the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13013] = { id = 13013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beldak the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13014] = { id = 13014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morthie the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13015] = { id = 13015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fargal the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
