quests[13017] = { id = 13017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarten the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
