quests[13034] = { id = 13034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witness and the Hero", description = "When I began my travels in Northrend, I visited the Borean Tundra and met the taunka for the first time. There, Wind Tamer Barah told me the tale of Stormhoof and his battle against the North Wind, their people's ancient enemy.\n\nI set out for the Storm Peaks to learn more of this hero, but strangely, the people of Tunka'lo seem to know nothing of him.\n\nPerhaps the camp's own records will give us greater insight. Find and read the history scrolls kept throughout the camp, then tell me what you learned.", sourceObjective = "Xarantaur, at Camp Tunka'lo, wants you to read the First History Scroll, the Second History Scroll, and the Third History Scroll.", progress = "What have you learned from the records of Camp Tunka'lo?", completion = "How peculiar... that doesn't sound like the story Wind Tamer Barah told me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13035] = { id = 13035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loken's Lackeys", description = "The attack on the Terrace of the Makers was not a half-hearted move on my brother's behalf.  He sent a legion of iron dwarves and some of his most powerful lieutenants.\n\nUse the Horn of the Peaks to call the earthen to your side and defeat Loken's servants.\n\nYou'll find the giant, Eisenfaust, inside the Hall of the Shaper to the north.  You'll find the others deeper inside the Terrace of the Makers, beyond the stairs to the northwest.", sourceObjective = "Thorim wants you to slay Eisenfaust inside the Hall of the Shaper and Halefnir the Windborn and Duronn the Runeforged in the Terrace of the Makers.", progress = "It's good to see you again, {name}.", completion = "One by one, my brother's servants have fallen.  Loken's insurrection will soon come to an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[13036] = { id = 13036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Above All Else", description = "Long has been the path to our salvation, young {class}. We have fought across continents, worlds even, to reach this point. Now we face our greatest challenge: the destruction of the Lich King and his Scourge.\n\nAlas, we fight this battle divided. The Horde and Alliance are in the throes of war and will lend us no support. We must remain unyielding in our cause! For what choice have we to do otherwise?\n\nDo you join the cause? Lend us your strength, {class}! My commander, Entari, awaits you at his post.", sourceObjective = "Report to Crusade Commander Entari at the Argent Vanguard in Icecrown.", completion = "Where both the Alliance and the Horde failed, the Argent Crusade succeeded. The success, however, was short lived. Our breach into Icecrown was quickly - and with force - rebuffed.\n\nThe Lich King's retaliatory strike was immediate and brutal. Now we are on the defensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[13037] = { id = 13037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Stormhoof", description = "When the bronze dragonflight gifted me with immortality and set me on the path of the witness, Nozdormu entrusted me with the Lorehammer.\n\nThe hammer's reaction to your findings means that time has gone awry here and it is our duty to restore the true timeline.\n\nWe must find it. To the northwest is Frostfloe Deep, ancient burial cave of the warriors of Tunka'lo. Seek out the spirit of Chieftain Swiftspear, Stormhoof's brother. Ask him what he remembers of his brother's battle against the North Wind.", sourceObjective = "Speak with Chieftain Swiftspear in Frostfloe Deep, then return to Xarantaur at Camp Tunka'lo.", progress = "What have you learned from spirit of Chieftain Swiftspear?", completion = "Even the chieftain is beginning to lose his memories? The past is being rewritten before our eyes and if we do not find out who is behind this, the entire legacy of Stormhoof could be lost forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[13038] = { id = 13038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distortions in Time", description = "This, the tomb of Tunka'lo's warriors, is supposed to be a serene place, free from the terror of the elements.\n\nFrostfloe Deep has been invaded by a strange force, one that disturbs the spirits of the fallen and blurs my memories of my own life.\n\nIt's as though our deeds and memories are being erased from history.\n\nIn life, this totem was a symbol of my authority. It is the last true link I have to this world. Take it, use it to restore calm to the tomb, and then return it to Camp Tunka'lo.", sourceObjective = "Use the Chieftain's Totem to close 4 Frostfloe Rifts, then bring the totem to Xarantaur at Camp Tunka'lo.", progress = "What is it you have brought from the tomb?", completion = "The chieftain's spirit told you to bring this to me?\n\n<Xarantaur examines the totem.>\n\nAh, I see what he intended. By telling you to use this totem to close the rifts in the deep, he has given us a clue as to what's happening to the timeline. A wise chieftain, this Swiftspear, watching over his people even in death.", sourceObjectiveStatus = "unverified-source-field" }
quests[13039] = { id = 13039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending The Vanguard", description = "We can't keep this pace up, <lad/lass>. Once the breach was blown, the floodgates opened up. The Scourge have been pourin' through ever since with no end in sight!\n\nWe need every able bodied man and woman to help keep the tide of evil at bay. Get out there and do yer share, friend. Kill as many of those monsters as ye can!", sourceObjective = "Crusader Lord Dalfors at the Argent Vanguard in Icecrown has asked that you kill 15 Forgotten Depths Nerubians.", progress = "Don't give up, {name}!", completion = "How many of them could there possibly be? We've killed enough to fill ten graveyards and still they come. The situation looks grim, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[13040] = { id = 13040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing The Incurable", description = "The number of injured soldiers rises with each passing day. They are being stricken by some type of toxin that we have never before seen. Whatever it is that these Nerubians hold within their venom glands is lethal and incurable! So far we've only been able to slow down the poison flowing through the victim's bodies. We must devise a cure!\n\nVenture northwest to the valley outside of the Vanguard and slay the Forgotten Depths Nerubians. Recover their venom glands and bring them to me.", sourceObjective = "Father Gustav at the Argent Vanguard in Icecrown has asked that you bring him 10 Forgotten Depths Venom Sacs.", progress = "Have you recovered the venom glands, {race}?", completion = "Thank you, {name}. I will begin the tests on these samples immediately. It is my hope that a cure will be found soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[13041] = { id = 13041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish the Shipment", description = "I'm glad you showed up!   A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one.\n\nBring me one and a Dalaran Jeweler's token will be yours.", sourceObjective = "Bring a Chalcedony to Timothy Jones in Dalaran.", progress = "Do you have the Chalcedony yet?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  I have new shipments going out all the time, check by from time to time to see what I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[13042] = { id = 13042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Bowels of The Underhalls", description = "Deep in the bowels of The Underhalls to the northeast, a mad scientist known as Dr. Terrible is up to something befitting his name.\n\nThe doctor has been given dispensation by the Lich King to perform experiments upon the vargul -- the vrykul who fall in battle and are found unworthy, and then turned into Scourge.\n\nWe must put an end to his work, but my auguries have been unable to find him. He does, however, have an assistant.\n\nBeat the information out of his apprentice, and then dispose of the body.", sourceObjective = "The Bone Witch in Njorndar Village has asked you to beat information out of Apprentice Osterkilgr concerning what Dr. Terrible is truly up to.\n\nYou are then to slay the apprentice.", progress = "You have not finished what I asked of you.\n\nPlease leave and do not return until you have done so or I will be very cross.", completion = "Very interesting. It sounds to me that you handled that perfectly. I'm surprised that the doctor was using a vargul as an assistant given what he was working on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13043] = { id = 13043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sum is Greater than the Parts", description = "Opening the tome, you notice all manner of disgusting illustrations concerning the construction of what the doctor refers to as \"the ultimate weapon\"!\n\nClearly the prototype, Nergeld, is the massive flesh giant standing still at the end of the nearby Hall of Horrors.\n\nIf an army of those things were to be constructed, then it would mean doom. The only way to ensure that doesn't happen is to slay Dr. Terrible!\n\nPerhaps if you were to take control of the construct, the doctor would reveal himself?", sourceObjective = "Mount and take control of Nergeld. Defend it from the denizens of the Hall of Horrors until Dr. Terrible shows himself.\n\nUse Nergeld to slay the doctor, and then return to The Bone Witch in Njorndar Village.", progress = "You recovered the doctor's tome, but you didn't finish him off using the flesh giant?\n\nGet back in there and kill him before it's too late!", completion = "You discovered and put an end to the doctor's machinations.\n\n<The banshee-controlled witch smiles and places a large hand gently upon your shoulder.>\n\nThat's a fine poke in the eye for the Lich King, but I think we can do better.", sourceObjectiveStatus = "unverified-source-field" }
quests[13044] = { id = 13044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If There Are Survivors...", description = "Across the Valley of Echoes, west of here, and through the Breach, is the first Scourge encampment in Icecrown known as Scourgeholme. We fought a good fight at Scourgeholme and killed many Scourge, but in the end we were forced to retreat. Many soldiers were left behind - their fate unknown.\n\nIf there are survivors, we must attempt a rescue. Directly down this southeastern path is Penumbrius, ally of the bronze dragonflight and caretaker of the proto-brood. Seek him out and ask for his assistance.", sourceObjective = "Speak with Penumbrius at the Argent Vanguard in Icecrown.", completion = "<Penumbrius nods.>\n\nMy kin will help. Together we will battle the Lich King and his undead legions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13045] = { id = 13045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Wild Green Yonder", description = "We will do all that we can to assist you, {name}. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.\n\nChoose one of the Argent Skytalons in the pen behind me and go!\n\nScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.", sourceObjective = "Rescue 3 Captured Argent Crusaders from Scourgeholme and drop them off at the Vanguard Infirmary at the center of the Argent Vanguard. Report to Highlord Tirion Fordring should you succeed.", progress = "With each minute that passes their chance of survival decreases.", completion = "Arthas... He strikes recklessly - without care or caution. We have caught him off guard.\n\n<Highlord Tirion Fordring pauses, lost in thought for a moment.>\n\nWe will bolster our defenses and weather the storm.\n\nHow good are you with a cannon, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13046] = { id = 13046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Arngrim", description = "Arngrim's hunger was legendary.\n\nEven in death, his expression is one of famished yearning. You find that just looking at him is making your stomach growl.\n\nIt is said that throughout his life he was never truly sated, and that there was absolutely nothing he wouldn't eat. You wonder to yourself if there might be a way to feed the old king.\n\nNo sooner does the thought enter your mind than one of the massive frozen teeth falls from Arngrim's head, bounces off of his beard and lands in your hand.", sourceObjective = "You are to feed Arngrim 5 Disembodied Jormungar, then return to Arngrim's frozen image in Dun Niffelem.\n\nYou must go to the Valley of Ancient Winters and use Arngrim's Tooth on the Roaming Jormungar there. Once they have become disembodied, you must fight them until they are weakened.", completion = "As you anchor the tooth in Arngrim's jaw, you get the impression that your efforts may have taken the edge off of the old king's hunger pangs... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13047] = { id = 13047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reckoning", description = "Loken killed my wife, turned my followers and me against each other.  He took away everything I had, but today... that changes.\n\nToday we reclaim our sacred grounds.  Today... Loken dies.\n\nMeet me on the bridge near the Temple of Wisdom, just southwest of Ulduar.  I will finish this one way or the other.\n\nI need you there as a witness.  You will not aid me -- this is personal.\n\nAfter it's done, send word to Jokkum, King of the Frost Giants.  He's a good friend and will know what to do.", sourceObjective = "Meet Thorim near the Temple of Wisdom. Report the outcome of the fight to King Jokkum in Dun Niffelem.", completion = "No... it cannot be...\n\nNo one can defeat Thorim in single combat.  Not a giant, nor a beast... no one!  Especially not that coward of a brother of his.\n\nOn my forefathers' names, this I swear...\n\nLoken will pay for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[13048] = { id = 13048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Time Went Wrong", description = "The Lorehammer can help us correct the damage to the timeline, but only if we can discover where the history was originally corrupted.\n\nFrom Chieftain Swiftspear and your findings at Frostfloe Deep, we know that the change happened around the time of Stormhoof's death.\n\nNow, you must go to the Howling Hollow, north of the camp, and inspect the gravesites the North Wind's minions have already destroyed. The Lorehammer will react to artifacts from Stormhoof's era and attune itself to the proper time.", sourceObjective = "Use the Lorehammer on Taunka Relics to attune it to the time of Stormhoof. Once it has been attuned to 6 relics from the time of Stormhoof, return to Xarantaur at Camp Tunka'lo.", progress = "Have you attuned the Lorehammer to the time period of Stormhoof?", completion = "<Xarantaur accepts the Lorehammer from you.>\n\nAt last, we've pinpointed the time of Stormhoof in history. With this knowledge, we can restore the timeline.", sourceObjectiveStatus = "unverified-source-field" }
quests[13049] = { id = 13049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero's Arms", description = "Not all of the camp's records have yet been corrupted. My staff has helped me to find those records which reflect the true timeline.\n\nThey agree that Stormhoof was given a burial of honor among the village elders on the bottom level of the Howling Hollow, to the north.\n\nMost of the graves there have already been destroyed, their contents taken as trophies by the North Wind's subjects. Go to the hollow and see if you can recover Stormhoof's spear and armor from the scions of storm who have claimed them.", sourceObjective = "Recover Stormhoof's Spear and Stormhoof's Mail and return them to Xarantaur at Camp Tunka'lo.", progress = "Have you found Stormhoof's weapon and armor?", completion = "We are fortunate that you have recovered these intact, {name}. With them, I can use the Lorehammer to send you back in time, to where the North Wind started to corrupt the true timeline. It's the only way we can restore the true history of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[13050] = { id = 13050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranus", description = "If I'm to launch an attack against my brother's army, I'm going to need some way to get around.\n\nI released my riding drake back into the wild years ago.  Veranus was magnificent.  The leader of her own brood -- to whom she has now returned.\n\nFinding her will be hard, but perhaps there's a way.  She keeps her old empty nest out of pure pride.  She's a broodmother in name only, for she is beyond the age of breeding.\n\nBring me small eggs from the other nests near Brunnhildar.  I think I've an idea.", sourceObjective = "Thorim, at the Temple of Storms, wants you to obtain 5 Small Proto-Drake Eggs from the peaks near Brunnhildar Village.", progress = "Did you obtain the eggs, {name}?", completion = "Yes... these will do.  Let us hope my plan works, {name}.\n\nVeranus is a great drake.  I'd hate to have to settle for a lesser one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13051] = { id = 13051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territorial Trespass", description = "Veranus is proud like no other beast I've known.  She still keeps her old nest and makes sure none of the younger proto-drakes takes it over.\n\nTake the eggs you've collected and place them on her nest.  You'll find it atop a small peak, directly southeast of here.\n\nI should be able to get control of her before she kills you in a fit of rage.  Hopefully.", sourceObjective = "Place the Stolen Proto-Dragon Eggs on top of the Broodmother's Nest and return to Thorim at the Temple of Storms.", progress = "Hail, {name}!", completion = "It's good to have my old friend back.  It appears that my luck is finally starting to change... and it's all thanks to you, little friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[13052] = { id = 13052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", sourceObjective = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest. I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing. Tell Vic I sent you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13053] = { id = 13053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Survivors", description = "Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition.  Apparently she thinks they're being held prisoner in the village to the north.\n\nThe only problem is I don't have a co-pilot.  If you're willing to take it on, I'd be more than happy to teach you a move or two.\n\nWhat do you say, {name}?  Deal?You will learn:", sourceObjective = "Help Zak Wobblesprocket complete the Test Flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13054] = { id = 13054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Tracker", description = "I can't in good conscience send you to the worg cave without warning you that the previous person we sent there hasn't returned.\n\nWe're prepared for the worst, but perhaps there's a chance that he's alive.  We'd appreciate it if you helped him return -- Tracker Val'zij is one of the only hunters we have.", sourceObjective = "Look for Tracker Val'zij inside Gimorak's Den, southeast of the Grom'arsh Crash Site.", completion = "This hurts bad, mon.  Don't know if I'm gonna make it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13055] = { id = 13055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave Medicine", description = "It's good to see a friendly face.  Might be the last one I see.\n\nOne of those jormungar stung me with some sort of toxin before I managed to get away.  I can feel my whole body getting numb, mon.\n\nI'm going to need a toxin gland to make an antidote.  I will also need some of the cave mushrooms that grow here... they'll slow the toxin down.\n\nHurry, please.  I don't have much time.", sourceObjective = "Tracker Val'zij, at Gimorak's Den, wants you to obtain 1 Jormungar Toxin Gland and 8 Cave Mushrooms.", progress = "You back, mon?", completion = "I thank you, mon.  I might live another day now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13056] = { id = 13056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Always Time for Revenge", description = "I should manage for now, {name}.  There is one favor I'd like to ask, though.\n\nI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I've seen in some time.\n\nDon't worry about me now, I'll feel better when that worg is breathing no more.  You should find him deeper in the cave.", sourceObjective = "Tracker Val'zij wants you to slay Gimorak inside Gimorak's Den.", progress = "You find that dirty mongrel, {name}?", completion = "I'm already feeling much better, mon.  Not sure if it's the antidote or the news of that filthy worg getting what he deserved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13057] = { id = 13057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrace of the Makers", description = "It is time, {name}.  I am prepared to face Loken now.\n\nLet us make our way to the Terrace of the Makers and face my brother's forces.  The fool will regret ever crossing me.", sourceObjective = "Find Thorim at the southeastern edge of the Terrace of the Makers, just northwest of Dun Niffelem.", completion = "We're here, {name}.  My brother's forces will learn the meaning of defeat today.", sourceObjectiveStatus = "unverified-source-field" }
quests[13058] = { id = 13058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing the Wind's Course", description = "At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona.\n\nTake the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens.\n\nThen, you must find and use the Horn of Elemental Fury to destroy the North Wind.", sourceObjective = "Use the Lorehammer to travel back in time and face the North Wind as Stormhoof. When Stormhoof falls and drops the Horn of Elemental Fury, use it to finish off the North Wind, and then return to Xarantaur at Camp Tunka'lo.", progress = "Have you done it? Is the true timeline restored?", completion = "What you have done today will ensure that Stormhoof and his story will never be forgotten. As well, you have written yourself into the pages of Azeroth's history. I will remember and record your accomplishments for all eternity.", sourceObjectiveStatus = "unverified-source-field" }
quests[13059] = { id = 13059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge for the Vargul", description = "I've been praying to The Lady of the Sword for one to come and strike down my enemy. Thane Illskar must pay for what he did to me!\n\nI was the champion of Thane Ufrang the Mighty. During my fight for ascendance in Valhalas, Illskar sabotaged me with dark magic, causing me to lose and be reduced to this.\n\nThe thane and his champions can be found below in The Circle of Suffering. Challenge him on my behalf. Defeat him.\n\nMake him know the suffering that I know!", sourceObjective = "Bethod Feigr in The Underhalls wants you to throw down his sword to challenge Thane Illskar and then kill him in The Circle of Suffering.", progress = "I sense that you haven't yet defeated Thane Illskar. Does something stay your hand?", completion = "Thank you, {class}... thank you!\n\nYou've given me the satisfaction of knowing that the coward who made me into this will rot for all eternity as surely as I will.\n\nNow leave before I lose control of myself and cut you down.", sourceObjectiveStatus = "unverified-source-field" }
quests[13060] = { id = 13060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", sourceObjective = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", completion = "<Olut winces.>\n\nThat looked painful. It was a pretty grand entrance though.\n\nAre you here to help us find a path into Icecrown? As you can see, our first foray in that direction didn't end too admirably. I'm thinking we might be better off breaching the place from another side.", sourceObjectiveStatus = "unverified-source-field" }
quests[13061] = { id = 13061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Glory", description = "This is it then.  I'll take care of your bear now, you won't be needing her.  The great Drakkensryd will be your next challenge.\n\nSay goodbye to your friends and leave your affairs in order, for you will return victorious... or you won't return at all.", sourceObjective = "Speak to Lok'lira the Crone in Brunnhildar Village.", completion = "You've really made it this far.  Never would I have thought you'd progress so quickly among the hyldnir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13062] = { id = 13062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok'lira's Parting Gift", description = "You've been a great ally, {name}.  Now comes your true test.  You will need skill, courage and a little luck.\n\n<Lok'lira attaches a thin strand of hair to yours.>\n\nYou cannot fail now sister.  Speak to Gretta the Arbiter.  She'll see you on your way.", sourceObjective = "Speak to Gretta the Arbiter in Brunnhildar Village.", completion = "Are you ready to ride, sister?  There is no coming back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13063] = { id = 13063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deemed Worthy", description = "You have succeeded where many have failed, sister. Whether it be by strength and courage or mere luck remains to be seen.\n\nGo back to the village and seek out Astrid Bjornrittar. Tell her of your accomplishments. But be warned. She is not easily impressed.", sourceObjective = "Brijana wants you to go to Brunnhildar Village and speak with Astrid Bjornrittar.", completion = "So, sister, you think that completing a few simple chores makes you a heroine?\n\nYou shall learn....", sourceObjectiveStatus = "unverified-source-field" }
quests[13064] = { id = 13064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sibling Rivalry", description = "Sif? Is it truly you?\n\nNo? A {race}? But for a moment....\n\nEnough of this! The visions of my Sif have tormented me for far too long. It is time for me to avenge her, and to bring honor to her memory.\n\nMy brother must pay!", sourceObjective = "Thorim wants you to listen to his story.", progress = "Hear my words, {race}.", completion = "You now know a bit of the history of this land... my land.\n\nI call upon you to assist me in setting these wrongs to right.", sourceObjectiveStatus = "unverified-source-field" }
quests[13065] = { id = 13065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohanzee the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13066] = { id = 13066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yurauk the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13067] = { id = 13067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chogan'gada the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[13068] = { id = 13068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Valor", description = "Perhaps you've heard the praises for our missing hero?\n\nCrusader Bridenbrad was in the Broken Front aiding the attack against the Scourge when the undead army came down upon them. The many men of that allied force scattered, but Bridenbrad alone returned and dragged more than a dozen men to safety, one by one through the carnage.\n\n{class}, he has not returned since. He was spotted heading to the far northeast, towards the Silent Vigil. Bring him back to me that I might honor him for his valor.", sourceObjective = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown. His fire pit will likely be the most obvious indication of his location from the air.", completion = "Back! Careful! The plague has gripped me and I'll not see it spread to you nor anyone else.", sourceObjectiveStatus = "unverified-source-field" }
quests[13069] = { id = 13069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoot 'Em Up", description = "Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They've concentrated these on their northern and western facings where they are most vulnerable.\n\nLet's use their defenses against them!\n\n<The Leaper pierces you with his single eye and cackles maniacally.>\n\nTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot 'em up!", sourceObjective = "The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.", completion = "You are a true champion for the cause, {name}!\n\nWon't you please come speak to me again tomorrow? I'm certain that there will be more of those nasty proto-drakes to shoot down.", sourceObjectiveStatus = "unverified-source-field" }
quests[13070] = { id = 13070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cold Front Approaches", description = "The chill of death stirs in the west, threatening to freeze our hearts and souls to this wasteland and bind us to its dark master. We will stand and we will fight!\n\nThe preparations have begun. Report to Siegemaster Fezzik at the front gate for your assignment.", sourceObjective = "Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.", completion = "We must be quick or face being overtaken by the Scourge! There's really no time for instructions, {race}. You're just going to have to jump in and hope for the best.", sourceObjectiveStatus = "unverified-source-field" }
quests[13071] = { id = 13071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Like Fire!", description = "Vile like fire! Vile like proto-drakes!\n\n<The abomination claps its hands excitedly.>\n\nLittle {name} go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!", sourceObjective = "Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.\n\nBalargarde Fortress, due to its nature, cannot be set ablaze.", progress = "What? Vile not see lots of fire!!!\n\n{name} go back and make more fire!", completion = "Yay, yay! {name} is best proto-drake stealer.\n\nYou come back tomorrow and we make more fire!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[13072] = { id = 13072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero Remains", description = "I know why you've come... they've sent you to bring me back, but that cannot happen. I carry the plague of undeath, {class}, and I'll not share my fate with those near me. No, I shall stay here.\n\nMy only regret lies in what I may become when death grips me. I do not fear death itself, but I loathe to consider serving the traitor, Arthas.\n\nLeave me... and see to it that no one else comes looking. You would do me a great disservice if you were to expose anyone to the plague that I carry.", sourceObjective = "Bring news of Crusader Bridenbrad's fate to Highlord Tirion Fordring at Crusaders' Pinnacle.", completion = "Bridenbrad has contracted the plague? I cannot imagine a worse fate for one who has devoted his life to the ways of light, nor can I fathom leaving him to die without lifting a finger to help.\n\nNo, undeath shall not be his fate. We shall find a way to aid this hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[13073] = { id = 13073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keeper's Favor", description = "There are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light.  And Bridenbrad, this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.\n\nGo now and speak to Arch Druid Lilliandra in the Argent Vanguard... request passage to Moonglade and seek the aid of Keeper Remulos.", sourceObjective = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.", completion = "Hello child.\n\nI understand Tirion's request and trust in his judgment, we will see what we can do for this Crusader Bridenbrad. What you ask is no simple task - the Scourge are not of this world, and many have failed in attempting to strip their corruption over the years.\n\nIn a being of nobility and light, all is not without hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[13074] = { id = 13074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Within the Emerald Nightmare", description = "What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.\n\nI will send you into the dream to recover some of these acorns. Be prepared though {class}, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.\n\nRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.", sourceObjective = "Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns.\n\nLeave the vicinity of the Shrine of Remulos to return to Azeroth.", progress = "It is good to see that you are safe. Have you recovered the acorns?", completion = "Excellent work, young one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13075] = { id = 13075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of Remulos", description = "I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.\n\nFarewell, {race}.", sourceObjective = "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn.", progress = "Well met, {class}. I knew that you would return, despite my warnings, but I'm pleased that you heeded my desire to not risk anyone else.\n\nWhy have you come back to me?", completion = "Tirion sent you to Remulos? I'm... I'm flattered. One does not call favors in with beings of such power idly, no matter how noble or altruistic they might be. You too are kind to have gone to such lengths on my behalf. You have my thanks.\n\nPlant the seed - I am ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[13076] = { id = 13076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Yet Remains", description = "I feel refreshed... renewed... but the plague still grips me. Not to worry, I am still eternally grateful that you went to such lengths for me, a complete stranger. If nothing else, you've bought me a few more precious hours not plaguing the world as a hideous undead.\n\nThank you, {class}. Please extend my thanks to Tirion as well, and let him know that it has been an honor to serve beside him.", sourceObjective = "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of Emerald Acorn's effects.", completion = "It saddens me to hear that it did not work. No reason to fret though, I have met other beings of good that may still be of aid to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[13077] = { id = 13077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Touch of an Aspect", description = "The dragon-queen, Alexstrasza, possesses magics over all life. In the past, she has used great fire to incinerate undead and rebirth fresh new life in their place. Perhaps her powers might be able to save our Bridenbrad as well.\n\nAlexstrasza makes her home at Wyrmrest Temple in Dragonblight - please go to her and humbly request her aid on my behalf.", sourceObjective = "Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple.", completion = "Greetings to you, {race}.\n\nThe concern is clear on your face. Please tell me what troubles you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13078] = { id = 13078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahlia's Tears", description = "In this dark time, I'll not be the one to abandon a champion of the Light.\n\nWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.\n\nGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia's Tears - bring them to me.", sourceObjective = "Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia's Tears from soil freshly cleansed by a Ruby Keeper's flames.", progress = "Ah, dear Dahlia. I do miss you so.", completion = "With Dahlia's Tears and ancient magic, I fashion you some small amount of hope for your great crusader.", sourceObjectiveStatus = "unverified-source-field" }
quests[13079] = { id = 13079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of Alexstrasza", description = "You must understand, young {race}, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.\n\nIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.", sourceObjective = "Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.", progress = "You have returned yet again, {class}. Why do you risk yourself so?", completion = "The breath of Alexstrasza... you have gone to the dragon-queen herself? I'm extremely grateful.\n\nI understand the risks of such cleansing and I am prepared. Proceed, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13080] = { id = 13080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Yet Remains", description = "<Bridenbrad raises a hand to you as he catches his breath.>\n\nIt was nearly as painful as it looked, but it was as if I could feel some of the corruption being burnt away from within my body. It seems the plague is not so readily bested though.\n\n{class}, thank you for everything that you have done. Your selfless actions have renewed my hope that there is yet great good left within this world - I can depart without fear that darkness will prevail in my absence.\n\nGo now, go with no regrets.", sourceObjective = "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of the effects of the Breath of Alexstrasza.", completion = "The Scourge plague is no simple foe to defeat. Alexstrasza's words suggest that perhaps we can yet save our Bridenbrad from the unimaginable fate of the unliving should he fall, but I will not give him up so easily.\n\nThere is yet one more path of light I would like to pursue. One more being who might avert this horrible fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13081] = { id = 13081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Naaru", description = "I appreciate everything that you have done for us, {name}. I have one last errand for you... one last gleaming hope for a paladin who deserves any salvation that we can extend.\n\nGo now to Shattrath and speak to the naaru, A'dal. He has long been a beacon of light and powerful ally to devout paladins. Impart Bridenbrad's story and seek any aid that he might have to offer.\n\nI cannot impress how important it is that you move quickly - I fear our crusader does not have much more time in this world.", sourceObjective = "Request the aid of A'dal at Shattrath City in Terokkar Forest.", completion = "<A gentle ringing fills your head as you approach the naaru.>\n\nI know why you have come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13082] = { id = 13082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of A'dal", description = "I am pleased that you have come to me, {name}. I know of Crusader Bridenbrad, and of your travels in hope of saving him. Bridenbrad's valor has sparked remarkable selflessness in you, and this is a miracle unto itself.\n\nThe Light will take care of its own. I will extend my blessing to Bridenbrad and he shall not endure the corruption of undeath. I shall return you to Dalaran, and you shall return to him. Know that I remain with you.", sourceObjective = "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown.", completion = "<As you approach Crusader Bridenbrad, you cannot help but notice that his skin has taken on a pale hue and his breaths are shallow. It is clear that he has little time left.>\n\nYou have returned to me, {class}. I must admit... it is good to see you again... your face renews my hope that this land will be free of Arthas's grasp one day soon. I'm proud to have met you...", sourceObjectiveStatus = "unverified-source-field" }
quests[13083] = { id = 13083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Within the Darkness", description = "<Crusader Bridenbrad's tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>\n\nTirion will desire this last remnant of the great crusader.", sourceObjective = "Bring Crusader Bridenbrad's Tabard to Highlord Tirion Fordring at Crusaders' Pinnacle.", progress = "He has departed, hasn't he? I felt a small bit of light leave the land.", completion = "I am glad you were able to save him from undeath. With A'dal's blessing, he will know no evil in his afterlife.\n\nWe shall take heart in his shining example and in your selflessness. Thank you for all that you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13084] = { id = 13084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vandalizing Jotunheim", description = "Let us see if we can further weaken the resolve of the vrykul, {name}.\n\nEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.\n\nAt least... it can't hurt.", sourceObjective = "Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners.", completion = "<The duke looks at you a moment and nods.>\n\nYou're inflicting horrible mental trauma on the Jotunheim vrykul. This is where they were first reawakened. It is a place of significant importance to them, second only to Ymirheim.\n\nYou must keep up the pressure there while I hold the vault from the assault of the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13085] = { id = 13085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaelen Has Returned", description = "I just saw that incompetent fool, Vaelen the Flayed, sneak into the vault building.\n\nGo see to it that he rectifies his mistake and returns my death knights to me!", sourceObjective = "Speak with Vaelen the Flayed at The Shadow Vault.", completion = "I think I can guess why you're here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13086] = { id = 13086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Line Of Defense", description = "I've triggered the base's defenses, {class}! Atop each of the Vanguard's four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You'll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.\n\nJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we're done for!", sourceObjective = "Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers.\n\nReturn to Siegemaster Fezzik should you succeed.", progress = "The screams of the dying will haunt me forever! Help them!", completion = "You handled the cannon like a goblin gunner, friend. You've saved the Vanguard and the Argent Crusade - all the while backing the Highlord himself up on the field of battle! Amazing!", sourceObjectiveStatus = "unverified-source-field" }
quests[13087] = { id = 13087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "So what are ya doin' if you dinna have any stew for me.   I got me a HUNGER!   At least bring me some chilled meat so I kin cook me own stew!   If ya do, I kin give ya the recipe so you kin make it for yourself.   NOW GO GET ME SOME MEAT!", sourceObjective = "Bring four chilled meat to Brom Brewbaster at Valgarde.  chilled meat can be found on any Northrend beast.", progress = "WHERE IS MY MEAT!", completion = "Ya gots me meat!   Here is your recipe, I gots cookin to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[13088] = { id = 13088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "We got a lot of new recruits here and these lads are hungry!  If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.", sourceObjective = "Bring four chilled meat to Rollick Mackreel at Valiance Keep.  chilled meat can be found on any Northrend beast.", progress = "The lads need meat for their stew.", completion = "That will keep our recruits fed!   Here's how you cook it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13089] = { id = 13089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.", sourceObjective = "Bring four chilled meat to Thomas Kolichio at Vengeance Landing.  chilled meat can be found on any Northrend beast.", progress = "The stew awaits...", completion = "We can quickly turn this flesh into stew.", sourceObjectiveStatus = "unverified-source-field" }
quests[13090] = { id = 13090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.", sourceObjective = "Bring four chilled meat to Orn Tenderhoof at Warsong Hold.  chilled meat can be found on any Northrend beast.", progress = "When the meat is present, the stew will be prepared.", completion = "I give my thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13091] = { id = 13091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Being a Water Terror", description = "The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!\n\n<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>\n\nGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!", sourceObjective = "The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region.\n\nQualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.", progress = "My reading of the bones tells me that you're not quite done.", completion = "I have never seen such terror in the eyes of a vrykul. They think themselves masters of their world.\n\nYou and I are going to prove them wrong. Very wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[13092] = { id = 13092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Bones", description = "One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one's fate.\n\n<The Bone Witch smirks.>\n\nLucky for you and I that I have it within my power to influence those readings.\n\nBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.", sourceObjective = "The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.", progress = "I find it remarkable that these beings ever held sway over the world when they utilized such primitive magic.", completion = "And now we shall see what the future holds for you.\n\n<The Bone Witch casts the bones upon the rug in front of her.>\n\nChoose your fate, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13093] = { id = 13093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Bones", progress = "Bring me more vrykul bones and we will influence the fates in your favor.", completion = "Choose your fate, {name}." }
quests[13094] = { id = 13094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Horde adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", sourceObjective = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, {name}, tell me you've found the book...", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13095] = { id = 13095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Alliance adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", sourceObjective = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, {name}, tell me you've found the book...", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13096] = { id = 13096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "Did ya see it, mon?\n\nIt musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nI done took an oath not ta be gettin' involved here. My job be to observe only. But dis cannot stand! Gal'darah must pay!\n\nGo into Gundrak and seek him out. Come back to me when Akali's death been avenged, mon.", sourceObjective = "Tol'mar at Dubra'Jin wants you to slay Gal'darah in Gundrak.", completion = "Ya done it?! Gal'darah be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to that wretch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13097] = { id = 13097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way north of Gundrak to Dubra'Jin and speak with Tol'mar. He will be able to direct you further in this cause.", sourceObjective = "Har'koa wants you to speak with Tol'mar at Dubra'jin.", completion = "Lissen up, mon. Dere be dangerous work ta be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[13098] = { id = 13098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Gundrak be doomed, mon.\n\nHistory be repeatin' itself before our eyes. When trolls be turnin' on their own gods, the end be certain. It just be a matter of time.\n\nPerhaps if we can record the events clearly, we might prevent future generations from traveling down da same path.\n\nIf you be havin' the courage, enter Gundrak and search for clues to what brought the Drakkari Empire to such an end as dis.", sourceObjective = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "<Bah'Kini scans the engraved tablets for a moment, then turns her attention back to you.>\n\nDese be authentic, {race}. I'll be placin' dem in their proper place in my collection.\n\nPerhaps we can finally be puttin' an end to dis behavior.", sourceObjectiveStatus = "unverified-source-field" }
quests[13099] = { id = 13099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from her post just west of Gundrak. Perhaps you could find the time to check in on her for me?", sourceObjective = "To'kini wants you to speak to Bah'kini at Dubra'Jin.", completion = "Long-time student? Hah!\n\nIf by long-time ya mean my whole life, den I suppose dat be accurate.\n\nTo'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!", sourceObjectiveStatus = "unverified-source-field" }
quests[13100] = { id = 13100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infused Mushroom Meatloaf", description = "We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.\n\nGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you're done, deliver the cooked meatloaf to Orton.", sourceObjective = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have any food for me?\n\nI never seem to be able to get away from the shop, even for a minute.", completion = "This looks great!  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[13101] = { id = 13101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convention at the Legerdemain", description = "Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!\n\nYou need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.\n\nBring the wine and stews to Arille.", sourceObjective = "Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food, I will have conventioneers here any minute!", completion = "This is plenty of food for everyone!  I am sure the customers will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13102] = { id = 13102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Stew", description = "Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.\n\nCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.\n\n You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.\n\nOnce the vegetable stew is ready, bring it to Ajay.", sourceObjective = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nOnce it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "I've got hungry people down here!  We need some stew.", completion = "This will be consumed in no time!   Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[13103] = { id = 13103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheese for Glowergold", description = "Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.\n\nCollect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.\n\nWe don't think he will know the difference.", sourceObjective = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.   I am quite peckish!", completion = "Aha, this appears to be a fine vintage!", sourceObjectiveStatus = "unverified-source-field" }
quests[13104] = { id = 13104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", sourceObjective = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "My knowledge of Scourge tactics is without equal.\n\n<The Ebon Watcher peers at you.>\n\nBefore the battle for Light's Hope Chapel, my knights and I served under the Lich King - his icy grasp controlling our every action. The light of dawn changed everything...", sourceObjectiveStatus = "unverified-source-field" }
quests[13105] = { id = 13105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", sourceObjective = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "Your power has grown, my faithful knight.\n\n<Highlord Darion Mograine peers at you.>\n\nVengeance is at hand, brother. Koltira aids the Horde upon the gunship, Orgrim's Hammer, while Thassarian assists the Alliance aboard the Skybreaker. The Ebon Blade will soon wash over Icecrown and leave the armies of the Lich King in ruin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13106] = { id = 13106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackwatch", description = "The Scourge has a large facility called the Fleshwerks, dedicated to producing abominations and flesh giants. If we can shut it down, we can deprive the Lich King of a large component of his armies.\n\nI've sent Darkrider Arly to the area. She has a small base, Blackwatch, on a ridge overlooking the Fleshwerks and to the west of Corp'rethar. I'm told the Argent Crusade is sending someone to coordinate their efforts there, but the darkrider will know what to do. Find and assist her.", sourceObjective = "Speak to Darkrider Arly at Blackwatch in Icecrown.", completion = "Good. We'll need all the help we can get. Olakin here is the Argent Crusade's contribution to our effort. Let's cut the chatter and get down to the business of denying the Scourge their armies of the flesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[13107] = { id = 13107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustard Dogs!", description = "Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.\n\nYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.\n\nBring him his picnic basket so he can be ready to go see the big game.", sourceObjective = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "I am almost ready to go, I just need the food and for my mates... er... my fellow mages to arrive.", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!", sourceObjectiveStatus = "unverified-source-field" }
quests[13108] = { id = 13108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nIf I have to rip him limb from limb myself, he soon shall pay for his wretched deeds.\n\nShould you meet with him before I do, the honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my blessing and gratitude.", sourceObjective = "King Jokkum in Dun Niffelem wants you to enter the Halls of Lightning and defeat Loken. You are then to return to King Jokkum with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little {race}.\n\nPlease accept this gift in return for your loyal friendship.", sourceObjectiveStatus = "unverified-source-field" }
quests[13109] = { id = 13109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nAs their leader, I wish nothing more than for their hearts to be mended and our friendship with the Stormlord to be renewed. In your defeat of Fjorn, a step has been taken down that path. I would have you bring us a step further...\n\nIn the Halls of Lightning, one even greater than Fjorn sits in opposition to our existence. Volkhan will not rest until either he, or we, are no more.", sourceObjective = "King Jokkum at Dun Niffelem wants you to enter the Halls of Lightning and defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little {race}. In time, I am certain my people will grow to forgive Thorim.", sourceObjectiveStatus = "unverified-source-field" }
quests[13110] = { id = 13110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Dead", description = "Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.\n\nTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.", sourceObjective = "Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.", progress = "It is a grim task, {name}, but it must be done.", completion = "The path of the righteous crusader is one beset by inequity and evil. To cut through the middle is the only salvation. You have done that on this day and much more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13111] = { id = 13111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Lissen, mon.\n\nAt first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nWhile dis be true, dere be somethin' special about dese Drakkari. If what I learned be true, den inside Gundrak dere be a special golem - one like nuthin' created before!\n\nYa want adventure, mon? Go inside Gundrak and bring me back a piece from dat golem ta study.", sourceObjective = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and recover a piece of the Drakkari Colossus.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[13112] = { id = 13112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infused Mushroom Meatloaf", description = "Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf.\n\nGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.\n\nIf only de council would let me serve me gnome specialty, I would show dem a real treat!", sourceObjective = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have something for me?  I so rarely get away from my shop.", completion = "Is this food from Awilo?  Can you promise me there isn't any gnome in it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13113] = { id = 13113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convention at the Legerdemain", description = "Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.\n\nArille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon.  You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.\n\nBring the wine and stew to Arille.", sourceObjective = "Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food?  My guests will be here soon!", completion = "My guests should find this acceptable.  Just don't tell them it came from Awilo.", sourceObjectiveStatus = "unverified-source-field" }
quests[13114] = { id = 13114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Stew", description = "We be havin' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon.\n\nHe asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.\n\nYou can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square.", sourceObjective = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nThen bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "Make sure there isn't any gnome in the stew this time!", completion = "Stew looks good.  Thanks for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13115] = { id = 13115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheese for Glowergold", description = "Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese.  Why he don't want some tasty gnome is beyond me.\n\nCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.\n\nYou can call da wine a Wine Medley, mon'.", sourceObjective = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.  I am quite peckish!", completion = "This wine is quite amazing!  I must know where it's from.", sourceObjectiveStatus = "unverified-source-field" }
quests[13116] = { id = 13116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustard Dogs!", description = "Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game.\n\nYou be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.\n\nFill up his basket with the mustard dog goodies, mon'.", sourceObjective = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "Make sure the wild mustard dogs are 100% rhino and have no Gnome in them!", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!", sourceObjectiveStatus = "unverified-source-field" }
quests[13117] = { id = 13117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are They Coming From?", description = "The Lich King's tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.\n\nYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.\n\nIf we do not discover where they're coming from and how they're able to work so quickly, we'll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.", sourceObjective = "Investigate a Summoning Altar in the eastern part of the Fleshwerks, then report back to Darkrider Arly at Blackwatch.", progress = "Have you found the source of the skeletons?", completion = "<You tell the darkrider about your discoveries at the summoning altar.>\n\nI suspected such. We can't let this continue. Our first priority is to destroy those summoning altars and then deal with the mess the Scourge has already created here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13118] = { id = 13118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purging Of Scourgeholme", description = "The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a 'slash and burn.' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.\n\nUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I'll ask no such thing of you. To succeed we must kill Scourge indiscriminately.\n\nVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill 3 Forgotten Depths High Priests, 3 Forgotten Depths Underkings, and 8 Reanimated Crusaders.", progress = "Do not waste time, {name}.", completion = "You have done well, {name}. Keeping their numbers down will give the Argent Crusade the time that they need to set a foundation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13119] = { id = 13119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Altars", description = "So they're summoning in their workers and warriors at those altars?\n\nThey'll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.\n\nDo this at all four of the altars and return to me once they've been destroyed.", sourceObjective = "Kill Master Summoner Zarod and use his Summoning Stave to destroy the First, Second, Third, and Fourth Summoning Altars. When you've completed this task, report to Darkrider Arly at Blackwatch.", progress = "Are the summoning altars in ruins?", completion = "<Darkrider Arly nods in approval.>\n\nGood. Now, we can focus our efforts on shutting down the rest of the Fleshwerks.", sourceObjectiveStatus = "unverified-source-field" }
quests[13120] = { id = 13120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Gaze", description = "The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.\n\n<Arly produces an orb from the folds of her cloak and shows it to you.>\n\nThis is a death's gaze orb. With it, we can observe the Scourge's actions and decide how best to strike.\n\nPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.", sourceObjective = "Use the Death's Gaze Orb to place orbs on the Abomination Lab Orb Stand, the Flesh Giant Lab Orb Stand, and the Cauldron Area Orb Stand, then return to Darkrider Arly at Blackwatch.", progress = "Have you placed those orbs?", completion = "<Darkrider Arly closes her eyes and seems to focus on something far away.>\n\nWith the eyes of death itself, I watch our enemy. With this knowledge, we will utterly destroy them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13121] = { id = 13121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Eye", description = "We must use the Lich King's tools against him if we are to decide our next step.\n\nOver the mountain to the southwest lies Kul'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.\n\nIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.", sourceObjective = "The Bone Witch in Njorndar Village has tasked you with using the Eye of the Lich King to gain information.", progress = "You return with no information at all! Is this how you repay my help to you and the Knights of the Ebon Blade?\n\nBegone and do not return until you have the knowledge which I seek!", completion = "Perfect! It's true that Iskalder is rumored to have been the finest vrykul warrior ever to live. And Vardmadra herself is going to come here to judge him!\n\nWe must move quickly if we are to get to this ancient hero before they do!", sourceObjectiveStatus = "unverified-source-field" }
quests[13122] = { id = 13122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scourgestone", description = "A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.\n\nWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.\n\nAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to bring him 15 Scourgestones.", progress = "Scourgestones will help us find our enemy.", completion = "Now let me see if there's something that I can do with these stones to give us a little bit of insight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13124] = { id = 13124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Struggle Persists", description = "Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.\n\nWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.", sourceObjective = "Raelorasz wants you to rescue Belgaristrasz and his companions in the Oculus.", completion = "Listen well, {race}.\n\nYour work here has just begun!", sourceObjectiveStatus = "unverified-source-field" }
quests[13125] = { id = 13125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Air Stands Still", description = "You must defeat the lords of Scourgeholme if this place is to be free of the Scourge's grasp.\n\nSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you'll find High Priest Yath'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.\n\nThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill Salranax the Flesh Render, Underking Talonox and High Priest Yath'amon.", progress = "Finish them, {name}!", completion = "A hard fought victory, {name}! The lieutenants will be replaced, but at least for today the air about Scourgeholme stands still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13126] = { id = 13126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Unified Front", description = "From here, it will take our combined efforts to proceed.\n\nAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield.\n\nWe can each provide you with drakes from our respective flights to help you reveal him.", sourceObjective = "Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos' shield. You then must defeat Varos Cloudstrider.", progress = "So, it is done!", completion = "It is as I had hoped, {race}. We work well together.\n\nMay our continued cooperation be enough to overcome the challenges that yet await!", sourceObjectiveStatus = "unverified-source-field" }
quests[13127] = { id = 13127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage-Lord Urom", description = "Only one obstacle stands between us and our ultimate goal here. His name is Urom.\n\nHe guards the third ring above us. Beware his powerful conjurings, friend.\n\nBring him down. Make him pay for his treacherous allegiance to the enemy!", sourceObjective = "Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus.", progress = "Has Mage-Lord Urom been dealt with?", completion = "Victory is in reach, friend.\n\nFocus, for now comes the true test.", sourceObjectiveStatus = "unverified-source-field" }
quests[13128] = { id = 13128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing and a Prayer", description = "The time has come to face Eregos.\n\nHe draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos.\n\nHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.", sourceObjective = "Belgaristrasz wants you to kill Eregos in the Oculus.", progress = "You've done it, haven't you? You bested Eregos!", completion = "I can already feel their defenses weakening!\n\nNot since the onset of this conflict have we dealt a blow of this magnitude to the Lord of Magic.\n\nDo not forget to visit Eregos' cache. Surely some of his treasures will interest you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13129] = { id = 13129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Games", description = "<Kurzel rips a long strip of material from her blouse and hands it to you.>\n\nHere, {race}, take this. Dip it in the remains of Novos the Summoner.\n\nWe're going to figure out what makes the Scourge leaders tick.", sourceObjective = "Kurzel wants you to use Kurzel's Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to her inside Drak'Tharon Keep.", progress = "Do you have the cloth?", completion = "Hopefully we can find somebody willing to examine this sample.", sourceObjectiveStatus = "unverified-source-field" }
quests[13130] = { id = 13130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone That Started A Revolution", description = "You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it \"Justice Keep.\"\n\nAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.\n\nTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.", sourceObjective = "Crusade Architect Silas at the Valley of Echoes in Icecrown wants you to retrieve 10 Trunks of Crystalline Heartwood and 10 pieces of Ancient Elven Masonry.", progress = "Are you lost?", completion = "Heartwood by nature is resistant to disease, rot and plague. This heartwood, however, goes so far as to repel such things! The masonry, affected by the fallout of the Unbound Thicket, will work in much the same way.\n\nSoon we will break ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[13131] = { id = 13131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junk in My Trunk", description = "Just look at it! Me trunk never been so empty.\n\nMe mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be!\n\nSay, thar be plenty o' loot farther in, an' not the cursed kind I'll wager.\n\nFetch it fer me an' I'll be rewardin' ya handsomely, matey.", sourceObjective = "Brigg in Utgarde Pinnacle wants you to find 5 Untarnished Silver Bars, 3 Shiny Baubles, 2 Golden Goblets, and a Jade Statue.", progress = "How'd yeh fare in thar, matey?", completion = "Brilliant! Ye've gone and done it, matey.\n\nNow I can show me face to the Cap'n without fearin' fer me life, thanks be ta you and yer mates.\n\nHere's a little booty fer you in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13132] = { id = 13132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Be Mine!", description = "Only luck spared me from the same fate as me mates.\n\nIn the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn.\n\nThere was a big ol' fella watchin' with a whole mess o' guards. They were chantin' Ymiron... maybe killin' him will free me mates?", sourceObjective = "Brigg in Utgarde Pinnacle wants you to kill King Ymiron.", progress = "Ya find the one in charge here, {race}? Did ya make 'em suffer?", completion = "Splendid! Mebbe now me mateys be able ta rest in peace.\n\nHere ya go, lad. Don't let it be said that ol' Brigg weren't generous ta those who showed 'im a kindness.\n\nGood doin' business wit yeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[13133] = { id = 13133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Ancient Hero", description = "Quickly, {name}, head southwest to the Halls of the Ancestors!\n\nWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.\n\nNow go. There is no time to waste!", sourceObjective = "The Bone Witch at Njorndar Village wants you to return with Iskalder.", progress = "Where is the ancient hero?\n\nWe do not have time to chat. Go to the Halls of the Ancestors and find him before it is too late!", completion = "He's a fine specimen and will serve us well.\n\nNow, we have to make sure to use him properly to trap Vardmadra!", sourceObjectiveStatus = "unverified-source-field" }
quests[13134] = { id = 13134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spill Their Blood", description = "The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.\n\nThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy 5 vats of Embalming Fluid and 5 Blood Orbs.", completion = "<A dark, hollow laugh greets you as you report to the darkrider.>\n\nYou reek of victory, {name}, and that is good news, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13135] = { id = 13135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Could Kill Us All", description = "Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!\n\nTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a \"win-win.\"", sourceObjective = "Crusade Engineer Spitzpatrick at the Valley of Echoes in Icecrown wants you to retrieve 8 pieces of Crystallized Energy.", progress = "Did you get the crystallized energy?", completion = "Ah, this is perfect. The bomber should be up and running in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13136] = { id = 13136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagged Shards", description = "You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.\n\nYou recall seeing similar shards embedded in the bodies of all the ghouls you've encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.", sourceObjective = "Bring 10 Jagged Shards to Crusader Olakin Sainrith at Blackwatch.", progress = "What is that vile thing?", completion = "<Olakin handles the shards of metal gingerly.>\n\nYou saw these on all of the ghouls down there? I've never seen anything like this in all my battles against the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13137] = { id = 13137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not-So-Honorable Combat", description = "Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.\n\nWe shall visit not-so-honorable combat upon it.\n\nGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.\n\nWe will fight, you will win, and Vardmadra is sure to come to witness the battle!", sourceObjective = "The Bone Witch in Njorndar Village wants you to defeat Iskalder upon Battlescar Spire.", progress = "You have yet to defeat the ancient hero!", completion = "I've put Vardmadra aside for the moment. She's someplace safe until we can enact our final revenge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13138] = { id = 13138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Smelting... Smelting!", description = "<Olakin turns one of the shards over in an armored fist.>\n\nThese could pierce armor with enough force. We have to find out what they're made of and what the Lich King intends to do with them.\n\nTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it's full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.", sourceObjective = "Use the Bag of Jagged Shards near one of the bottom level Malykriss furnaces. Return to Crusader Olakin Sainrith at Blackwatch with the Smelted Metal Bar.", progress = "Have you smelted those fragments yet?", completion = "There is no doubt, this is raw saronite. We've seen weapons made from it in the hands of the Lich King's chosen before, but this is the first time it's been used to arm anything else. The scale of that mining operation must be huge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13139] = { id = 13139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Frozen Heart Of Northrend", description = "Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.\n\nI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.", sourceObjective = "Deliver Father Gustav's Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", progress = "Stand easy, {name}. What have you to report?", completion = "Your assistance has been integral in securing the front. The first true victory of this war is close at hand - which is why our next step is the most crucial.\n\nRest assured, {name}, the Scourge will not give up without a fight. Your most difficult challenge awaits.", sourceObjectiveStatus = "unverified-source-field" }
quests[13140] = { id = 13140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runesmiths of Malykriss", description = "Those shards you recovered can only have come from one place, Malykriss. It's the seat of the Lich King's metalworking operations, to the east of Corp'rethar.\n\nWhat's puzzling is that metal isn't needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they're working on. We need to find out why this metal is finding its way to the Fleshwerks.", sourceObjective = "Bring 5 Runed Saronite Plates to Crusader Olakin Sainrith at Blackwatch.", progress = "Were you able to capture those rune plates?", completion = "These plates match the shards almost exactly. They must be using cuttings from them to \"enhance\" the ghouls produced here. The Scourge is desperate enough to make a weapon of anything, it seems. All the more reason to hasten our destruction of this abominable place!", sourceObjectiveStatus = "unverified-source-field" }
quests[13141] = { id = 13141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For Crusaders' Pinnacle", description = "<Highlord Fordring holds a banner of the Argent Crusade.>\n\nThis banner is like no other, {name}. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.\n\nYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.\n\nGo now, {name}. Hold no fear in your heart.", sourceObjective = "Venture to Crusaders' Pinnacle and use the Blessed Banner of the Crusade atop the Pile of Crusader Skulls. Defend the banner against Scourge attack until the land atop the pinnacle is sanctified and then return to Father Gustav at the Valley of Echoes in Icecrown.", progress = "Have we broken ground?", completion = "Blessed Light! We have taken the pinnacle! Finally, construction of Justice Keep can begin. Highlord Fordring and the knights are already en route to our new base. You must meet them there, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13142] = { id = 13142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banshee's Revenge", description = "The time has come, {name}. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.\n\nAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.\n\nBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.\n\n<The banshee-possessed vrykul lets out a bellowing cackle.>", sourceObjective = "The Bone Witch at Njorndar Village has asked you to exact her revenge by challenging and defeating Overthane Balargarde.", progress = "Overthane Balargarde is not dead. Did you have problems finding his fortress?", completion = "Words cannot describe what I'm feeling at the moment, {name}. My revenge is complete and there is naught else for me to do.\n\nIf only I could be there when the Lich King is finally taken down.\n\nDon't fool yourself though, Jotunheim is far from 'dealt' with. I will remain in possession of this witch until such time as the vrykul are no longer a threat.\n\nLook around, there are many items of value in this cave. Take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[13143] = { id = 13143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Recruit", description = "First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they're about as perfect a scout as you can get... with a little prodding from an eye of dominion.\n\nFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.", sourceObjective = "Vereth the Cunning on the Rise of Suffering has requested that you bring a subdued Lithe Stalker to the top of the rocks northeast of the Rise of Suffering.", progress = "I'm sure their new masters don't go easy on them, but there's no way these things would forget the lessons we lashed into their skins. They'll fear those sigils for as long as they crawl this land.", completion = "I've chained the wretch to the post over there and I'll look into getting my hands on more of them.\n\nNow let's make some use of that eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[13144] = { id = 13144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing Two Scourge With One Skeleton", description = "The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King's armies.\n\nGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy 3 Chained Abominations with Burning Skeletons.", progress = "Have you destroyed the completed abominations?", completion = "Ah, good. There's nothing like the smell of roasted putrid flesh in the morning. That's the smell of victory over the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13145] = { id = 13145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Hold", description = "We need to know what we're up against.\n\nUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.\n\nThe stalker can leap far and won't be hurt by large falls - use that to your advantage to get up and down from those ramparts.", sourceObjective = "Vereth the Cunning at the Rise of Suffering has requested that you use a Lithe Stalker to scout out Malykriss.", progress = "Flying may be a bit more graceful, but there's no way that we could get in as close as the stalker can without being detected.", completion = "Excellent work. It seems more death knights remained loyal to Arthas than I initially thought.\n\nHe certainly is sparing nothing in his attempt to replace Acherus. A pure saronite citadel would be hard to destroy indeed. There's no need to destroy it though... we can halt production and put down these death knight leaders here and now, before they become a real threat.\n\nMost importantly, we need to disrupt them enough to get those death knights away from from the leaders so that we can make our strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[13146] = { id = 13146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Generosity Abounds", description = "We need to cause some disruption to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they'll have to devote more attention to keeping a close eye on operations.\n\nAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them near some of the Scourge bombs scattered throughout the construction area. You'll be able to light the bombs far before they figure out what's going on.", sourceObjective = "Vereth the Cunning wants you to use the Lithe Stalker's Iron Chain to drag Scourge Bombs to 4 Lumbering Atrocities inside Malykriss.", progress = "Did they even see it coming?", completion = "They didn't even think to lay a hand on you, did they? At least they're predictable.", sourceObjectiveStatus = "unverified-source-field" }
quests[13147] = { id = 13147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matchmaker", description = "The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.\n\nLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.\n\nShould be simple - throw rocks at the brutes as they near lesser undead.", sourceObjective = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker to throw rocks at Umbral Brutes as they near lesser undead in Malykriss. Return after you've started 5 fights.", progress = "Predictable louts.", completion = "No need to sacrifice our own men when they are this easily manipulated, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[13148] = { id = 13148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necklace Repair", description = "This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\".\n\nPerhaps you should repair it and return it to him.", sourceObjective = "Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran.", progress = "What brings you here?", completion = "How did you find this!   Many of these necklaces were looted from one of my shipments a few weeks ago!   Let me repay you with this Jewelcrafter's Token.", sourceObjectiveStatus = "unverified-source-field" }
quests[13149] = { id = 13149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispelling Illusions", description = "The infinite dragonflight seek to disrupt history by deceiving Prince Arthas.\n\nIf they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme.\n\nUse this arcane disruptor on any suspicious crates of grain you find.", sourceObjective = "Chromie wants you to use the Arcane Disruptor on the suspicious crates in Stratholme Past, then speak to her near the entrance to Stratholme.", progress = "Well done, friend.\n\nArthas' forces have discovered the plagued grain.", completion = "You have done well, friend. The plagued grain was exposed to Arthas' troops.\n\nListen carefully, now. There remains more to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13150] = { id = 13150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDLost: Widget", description = "Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.   Perhaps if you fixed it and returned it to him, he would have a reward for you.", sourceObjective = "Repair the whatsit and return it to Timothy Jones at the Jewelcrafting shop in Dalaran.Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.  Perhaps if you fixed it and returned it to him, he would have a reward for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13151] = { id = 13151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Escort", description = "Arthas will soon face a desperate dilemma, and make a momentous decision.\n\nI must call upon you to accompany the prince in his culling.\n\nArthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!", sourceObjective = "Chromie has asked you to accompany Arthas in the Culling of Stratholme. You are to speak with her again after Mal'Ganis is defeated.", completion = "You have done well, {name}.\n\nThe Infinites have been foiled and this thread of history remains intact.\n\nI thank you for your invaluable assistance, as does the entire Bronze Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13152] = { id = 13152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit to the Doctor", description = "So they've been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.\n\nFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy the Metal Stake imprisoning Patches in the Sanctum of Reanimation and help him get his revenge on Doctor Sabnok.", progress = "Have you unleashed the doctor's creation against him?", completion = "<Dakrider Arly throws her head back and laughs darkly.>\n\nA fitting end for the 'good' doctor, wouldn't you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[13153] = { id = 13153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Warriors", description = "{name}, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", sourceObjective = "Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?", sourceObjectiveStatus = "unverified-source-field" }
quests[13154] = { id = 13154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", sourceObjective = "Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13155] = { id = 13155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereth the Cunning", description = "I've already heard some rumors regarding Malykriss and Arthas's new death knight order, but I assumed it nothing more than filling the void. These numbers suggest he's trying to take it up a notch though.\n\nWe dispatched one of our best to Malykriss not long ago - Vereth the Cunning. You should be able to find him on the Rise of Suffering, just west of Malykriss, and inside the Court of Bones.\n\nTry not to draw too much attention on your way in.", sourceObjective = "Report to Vereth the Cunning on the Rise of Suffering in Icecrown.", completion = "The Vile Hold... a testament to how much Arthas hates losing. Let's drive the blade deep.", sourceObjectiveStatus = "unverified-source-field" }
